import { InsForgeClient } from '../client';
import type { InsForgeConfig, InsForgeError } from '../types';
import { createServerClient } from './server-client';
import {
  clearAuthCookies,
  setAuthCookies,
  type AuthCookieSettings,
  type CookieStore,
  type CookieWriter,
} from './cookies';

export interface CreateAuthActionsOptions
  extends
    Omit<InsForgeConfig, 'accessToken' | 'edgeFunctionToken' | 'isServerMode' | 'auth'>,
    AuthCookieSettings {
  /**
   * Read/write cookie store. Use this in Next.js Server Actions:
   * `createAuthActions({ cookies: await cookies() })`.
   */
  cookies?: CookieStore;

  /**
   * Request cookie reader. Use with `responseCookies` in Route Handlers where
   * request and response cookies are separate objects.
   */
  requestCookies?: Pick<CookieStore, 'get'>;

  /**
   * Response cookie writer. Use with `requestCookies` in Route Handlers.
   */
  responseCookies?: CookieWriter;
}

type AuthTokenKeys = 'accessToken' | 'refreshToken' | 'csrfToken';
type SafeAuthData<T> = Omit<NonNullable<T>, AuthTokenKeys>;
type AuthResultData<TMethod extends (...args: any[]) => Promise<any>> =
  Awaited<ReturnType<TMethod>> extends { data: infer TData } ? TData : never;
type SafeAuthAction<TMethod extends (...args: any[]) => Promise<any>> = (
  ...args: Parameters<TMethod>
) => Promise<{
  data: SafeAuthData<AuthResultData<TMethod>> | null;
  error: InsForgeError | null;
}>;

export interface AuthActions {
  signUp: SafeAuthAction<InsForgeClient['auth']['signUp']>;
  signInWithPassword: SafeAuthAction<InsForgeClient['auth']['signInWithPassword']>;
  signInWithOAuth: InsForgeClient['auth']['signInWithOAuth'];
  signInWithIdToken: SafeAuthAction<InsForgeClient['auth']['signInWithIdToken']>;
  exchangeOAuthCode: SafeAuthAction<InsForgeClient['auth']['exchangeOAuthCode']>;
  verifyEmail: SafeAuthAction<InsForgeClient['auth']['verifyEmail']>;
  signInWithOtp: InsForgeClient['auth']['signInWithOtp'];
  verifyOtp: SafeAuthAction<InsForgeClient['auth']['verifyOtp']>;
  signOut: InsForgeClient['auth']['signOut'];
}

function persistSessionCookies(
  cookies: CookieWriter | undefined,
  data: { accessToken?: string | null; refreshToken?: string | null } | null,
  settings: AuthCookieSettings
): void {
  if (!data?.accessToken) {
    return;
  }

  setAuthCookies(
    cookies,
    {
      accessToken: data.accessToken,
      refreshToken: data.refreshToken,
    },
    settings
  );
}

function sanitizeAuthData<T>(data: T | null): SafeAuthData<T> | null {
  if (!data) {
    return null;
  }

  const {
    accessToken: _accessToken,
    refreshToken: _refreshToken,
    csrfToken: _csrfToken,
    ...safeData
  } = data as Record<string, unknown>;

  return safeData as SafeAuthData<T>;
}

function toSafeAuthResult<TMethod extends (...args: any[]) => Promise<any>>(
  result: Awaited<ReturnType<TMethod>>
): Awaited<ReturnType<SafeAuthAction<TMethod>>> {
  return {
    data: sanitizeAuthData(result.data),
    error: result.error,
  };
}

export function createAuthActions(options: CreateAuthActionsOptions = {}): AuthActions {
  const {
    cookies,
    requestCookies,
    responseCookies,
    names,
    options: cookieOptions,
    ...clientOptions
  } = options;
  const readCookies = requestCookies ?? cookies;
  const writeCookies = responseCookies ?? cookies;
  if (!writeCookies?.set) {
    throw new Error(
      'createAuthActions() requires a writable cookie store. Pass cookies in Server Actions or responseCookies in Route Handlers.'
    );
  }

  const cookieSettings: AuthCookieSettings = {
    names,
    options: cookieOptions,
  };

  const createClient = () =>
    createServerClient({
      ...clientOptions,
      names,
      options: cookieOptions,
      cookies: readCookies,
    });

  return {
    signUp: async (request) => {
      const result = await createClient().auth.signUp(request);
      persistSessionCookies(writeCookies, result.data, cookieSettings);
      return toSafeAuthResult<InsForgeClient['auth']['signUp']>(result);
    },

    signInWithPassword: async (request) => {
      const result = await createClient().auth.signInWithPassword(request);
      persistSessionCookies(writeCookies, result.data, cookieSettings);
      return toSafeAuthResult<InsForgeClient['auth']['signInWithPassword']>(result);
    },

    signInWithOAuth: async (providerOrOptions: any, signInOptions?: any) => {
      return createClient().auth.signInWithOAuth(providerOrOptions, signInOptions);
    },

    signInWithIdToken: async (credentials) => {
      const result = await createClient().auth.signInWithIdToken(credentials);
      persistSessionCookies(writeCookies, result.data, cookieSettings);
      return toSafeAuthResult<InsForgeClient['auth']['signInWithIdToken']>(result);
    },

    exchangeOAuthCode: async (code, codeVerifier) => {
      const result = await createClient().auth.exchangeOAuthCode(code, codeVerifier);
      persistSessionCookies(writeCookies, result.data, cookieSettings);
      return toSafeAuthResult<InsForgeClient['auth']['exchangeOAuthCode']>(result);
    },

    verifyEmail: async (request) => {
      const result = await createClient().auth.verifyEmail(request);
      persistSessionCookies(writeCookies, result.data, cookieSettings);
      return toSafeAuthResult<InsForgeClient['auth']['verifyEmail']>(result);
    },

    signInWithOtp: async (request) => {
      return createClient().auth.signInWithOtp(request);
    },

    verifyOtp: async (request) => {
      const result = await createClient().auth.verifyOtp(request);
      persistSessionCookies(writeCookies, result.data, cookieSettings);
      return toSafeAuthResult<InsForgeClient['auth']['verifyOtp']>(result);
    },

    signOut: async () => {
      const result = await createClient().auth.signOut();
      clearAuthCookies(writeCookies, cookieSettings);
      return result;
    },
  };
}

/**
 * Shared setup for integration tests.
 *
 * Environment variables:
 *   INSFORGE_INTEGRATION_BASE_URL  – required, e.g. https://xxx.us-east.insforge.app
 *   INSFORGE_INTEGRATION_ANON_KEY  – required, project anon key
 *
 * The suite creates its own users so no pre-existing credentials are needed.
 */

import { InsForgeClient } from '../src/client';
import { createClient as createClientFactory } from '../src/index';

// ---------------------------------------------------------------------------
// Environment helpers
// ---------------------------------------------------------------------------

export interface TestEnv {
  baseUrl: string;
  anonKey: string;
}

let _env: TestEnv | null = null;

export function getTestEnv(): TestEnv {
  if (_env) {
    return _env;
  }

  const baseUrl = (
    process.env.INSFORGE_INTEGRATION_BASE_URL ||
    process.env.INSFORGE_TEST_URL ||
    ''
  ).replace(/\/+$/, '');

  const anonKey =
    process.env.INSFORGE_INTEGRATION_ANON_KEY || process.env.INSFORGE_TEST_ANON_KEY || '';

  if (!baseUrl) {
    throw new Error(
      'Missing INSFORGE_INTEGRATION_BASE_URL. Example:\n' +
        '  INSFORGE_INTEGRATION_BASE_URL=https://gv5eyqe5.us-east.insforge.app \\\n' +
        '  INSFORGE_INTEGRATION_ANON_KEY=<key> \\\n' +
        '  npm run test:integration'
    );
  }

  if (!anonKey) {
    throw new Error('Missing INSFORGE_INTEGRATION_ANON_KEY. Provide the project anon key.');
  }

  _env = { baseUrl, anonKey };
  return _env;
}

// ---------------------------------------------------------------------------
// Client factories
// ---------------------------------------------------------------------------

/** Create a plain (unauthenticated) client in server mode. */
export function createClient(overrides?: Partial<TestEnv>): InsForgeClient {
  const env = getTestEnv();
  return new InsForgeClient({
    baseUrl: overrides?.baseUrl ?? env.baseUrl,
    anonKey: overrides?.anonKey ?? env.anonKey,
    isServerMode: true,
  });
}

/** Same thing using the `createClient` factory export (covers that code path). */
export function createClientViaFactory(overrides?: Partial<TestEnv>): InsForgeClient {
  const env = getTestEnv();
  return createClientFactory({
    baseUrl: overrides?.baseUrl ?? env.baseUrl,
    anonKey: overrides?.anonKey ?? env.anonKey,
    isServerMode: true,
  });
}

// ---------------------------------------------------------------------------
// Test-user helpers
// ---------------------------------------------------------------------------

/** Generate a unique email that won't collide across parallel runs. */
export function uniqueEmail(prefix = 'sdktest'): string {
  const ts = Date.now();
  const rand = Math.random().toString(36).slice(2, 8);
  return `${prefix}+${ts}-${rand}@test.insforge.dev`;
}

const TEST_PASSWORD = 'Test_P@ssword_123!';

export { TEST_PASSWORD };

// ---------------------------------------------------------------------------
// Fixed test account (pre-verified, for authenticated tests)
// ---------------------------------------------------------------------------

function getFixedTestAccount() {
  const email = process.env.INSFORGE_INTEGRATION_TEST_EMAIL || '';
  const password = process.env.INSFORGE_INTEGRATION_TEST_PASSWORD || '';

  if (!email || !password) {
    throw new Error(
      'Missing INSFORGE_INTEGRATION_TEST_EMAIL or INSFORGE_INTEGRATION_TEST_PASSWORD.\n' +
        'These must be a pre-verified account for authenticated integration tests.'
    );
  }

  return { email, password };
}

/**
 * Sign in with a fixed pre-verified account and return an authenticated client.
 *
 * Used by most test files (ai, database, storage, realtime, email) that
 * need a valid auth session. Since email verification is enabled,
 * freshly signed-up users cannot authenticate — use this instead.
 */
export async function signUpAndSignIn() {
  const { email, password } = getFixedTestAccount();
  const client = createClient();

  const { data, error } = await client.auth.signInWithPassword({ email, password });

  if (error) {
    return { client, email, password, data: null, error };
  }

  return { client, email, password, data, error: null };
}

/**
 * Sign up a fresh (unverified) user. Used by auth tests that specifically
 * test the registration flow, profile updates, verification, etc.
 *
 * The returned client may NOT have a valid auth session (email verification
 * required). Callers should handle this accordingly.
 */
export async function signUpFreshUser() {
  const email = uniqueEmail();
  const client = createClient();

  const { data, error } = await client.auth.signUp({
    email,
    password: TEST_PASSWORD,
    name: 'SDK Integration Test',
  });

  return { client, email, password: TEST_PASSWORD, data, error };
}

import { describe, it, expect, beforeAll } from 'vitest';
import {
  createClient,
  uniqueEmail,
  signUpFreshUser,
  signUpAndSignIn,
  TEST_PASSWORD,
} from './setup';
import type { InsForgeClient } from '../src/client';

describe('Auth Module', () => {
  let client: InsForgeClient;

  beforeAll(() => {
    client = createClient();
  });

  // ================================================================
  // getPublicAuthConfig  (no auth required)
  // ================================================================

  describe('getPublicAuthConfig()', () => {
    it('should return the project auth configuration', async () => {
      const { data, error } = await client.auth.getPublicAuthConfig();
      expect(error).toBeNull();
      expect(data).toBeDefined();
      expect(data).not.toBeNull();
    });
  });

  // ================================================================
  // signUp
  // ================================================================

  describe('signUp()', () => {
    it('should create a new user and return user data', async () => {
      const email = uniqueEmail('signup');
      const { data, error } = await client.auth.signUp({
        email,
        password: TEST_PASSWORD,
        name: 'Signup Test',
      });

      expect(error).toBeNull();
      expect(data).not.toBeNull();

      if (data!.user) {
        // When email verification is NOT required, user and token are returned
        expect(data!.user.email).toBe(email);
        expect(data!.user.id).toBeDefined();
        expect(data!.accessToken).toBeDefined();
      } else {
        // When email verification IS required, signUp succeeds but
        // user/accessToken may be absent until the email is verified
        expect(data).toBeDefined();
      }
    });

    it('should reject a duplicate email', async () => {
      const email = uniqueEmail('dup');

      const first = await client.auth.signUp({
        email,
        password: TEST_PASSWORD,
        name: 'First',
      });
      expect(first.error).toBeNull();

      const second = await client.auth.signUp({
        email,
        password: TEST_PASSWORD,
        name: 'Second',
      });
      expect(second.error).not.toBeNull();
      expect(second.error!.statusCode).toBeGreaterThanOrEqual(400);
    });

    it('should reject a weak / empty password', async () => {
      const { error } = await client.auth.signUp({
        email: uniqueEmail('weak'),
        password: '12',
        name: 'Weak',
      });
      expect(error).not.toBeNull();
    });

    it('should reject missing email', async () => {
      const { error } = await client.auth.signUp({
        email: '',
        password: TEST_PASSWORD,
        name: 'No Email',
      });
      expect(error).not.toBeNull();
    });
  });

  // ================================================================
  // signInWithPassword
  // ================================================================

  describe('signInWithPassword()', () => {
    let testEmail: string;

    beforeAll(async () => {
      testEmail = uniqueEmail('signin');
      const c = createClient();
      const { error } = await c.auth.signUp({
        email: testEmail,
        password: TEST_PASSWORD,
        name: 'Sign-In Test',
      });
      expect(error).toBeNull();
    });

    it('should sign in with correct credentials or require email verification', async () => {
      const c = createClient();
      const { data, error } = await c.auth.signInWithPassword({
        email: testEmail,
        password: TEST_PASSWORD,
      });

      if (error) {
        // Projects with email verification enabled return an error here
        // The error should be structured and related to verification
        expect(error.statusCode).toBeGreaterThanOrEqual(400);
        expect(typeof error.message).toBe('string');
      } else {
        expect(data).not.toBeNull();
        expect(data!.accessToken).toBeDefined();
        expect(data!.user).toBeDefined();
        expect(data!.user.email).toBe(testEmail);
      }
    });

    it('should reject wrong password', async () => {
      const c = createClient();
      const { error } = await c.auth.signInWithPassword({
        email: testEmail,
        password: 'Wrong_P@ssword_999!',
      });
      expect(error).not.toBeNull();
      expect(error!.statusCode).toBeGreaterThanOrEqual(400);
    });

    it('should reject non-existent email', async () => {
      const c = createClient();
      const { error } = await c.auth.signInWithPassword({
        email: `ghost-${Date.now()}@test.insforge.dev`,
        password: TEST_PASSWORD,
      });
      expect(error).not.toBeNull();
    });
  });

  // ================================================================
  // getCurrentUser
  // ================================================================

  describe('getCurrentUser()', () => {
    it('should return the user after sign-up', async () => {
      const { client: authed, data: signUpData, error: err } = await signUpFreshUser();
      expect(err).toBeNull();

      const { data, error } = await authed.auth.getCurrentUser();

      // In server mode, getCurrentUser checks tokenManager
      // signUp sets the token, so user should be available
      if (signUpData?.accessToken && typeof signUpData.accessToken === 'string') {
        expect(error).toBeNull();
        expect(data.user).not.toBeNull();
      } else {
        // If signUp didn't return a usable token, user may be null
        expect(data).toBeDefined();
      }
    });

    it('should return null user for unauthenticated client', async () => {
      const anon = createClient();
      const { data } = await anon.auth.getCurrentUser();
      expect(data.user).toBeNull();
    });
  });

  // ================================================================
  // refreshSession  (server mode – needs refreshToken)
  // ================================================================

  describe('refreshSession()', () => {
    it('should return error when called in server mode without refreshToken', async () => {
      const { client: authed, error: err } = await signUpFreshUser();
      expect(err).toBeNull();

      const { error } = await authed.auth.refreshSession();
      // In server mode, missing refreshToken is an explicit error
      expect(error).not.toBeNull();
      expect(error!.message).toContain('refreshToken');
    });

    it('should refresh when a valid refreshToken is provided', async () => {
      const { client: authed, data, error: signErr } = await signUpAndSignIn();
      if (signErr) {
        console.log('Skipping refresh test – signUp/signIn failed:', signErr.message);
        return;
      }

      // Response may include a refreshToken in server mode
      const refreshToken = (data as any)?.refreshToken;
      if (!refreshToken) {
        console.log('refreshToken not returned – skipping refresh test');
        return;
      }

      const { data: refreshed, error } = await authed.auth.refreshSession({
        refreshToken,
      });

      expect(error).toBeNull();
      expect(refreshed).not.toBeNull();
      expect(refreshed!.accessToken).toBeDefined();
    });
  });

  // ================================================================
  // signOut
  // ================================================================

  describe('signOut()', () => {
    it('should sign out without error', async () => {
      const { client: authed, error: err } = await signUpFreshUser();
      expect(err).toBeNull();

      const { error } = await authed.auth.signOut();
      expect(error).toBeNull();
    });

    it('should clear the session so getCurrentUser returns null', async () => {
      const { client: authed, error: err } = await signUpFreshUser();
      expect(err).toBeNull();

      const { error: signOutErr } = await authed.auth.signOut();
      expect(signOutErr).toBeNull();

      // After sign-out, user should be null in server mode
      const { data } = await authed.auth.getCurrentUser();
      expect(data.user).toBeNull();
    });
  });

  // ================================================================
  // getProfile / setProfile
  // ================================================================

  describe('getProfile() / setProfile()', () => {
    it('should get a user profile by ID', async () => {
      const { client: authed, data: signUpData, error: err } = await signUpFreshUser();
      expect(err).toBeNull();

      const userId = signUpData?.user?.id;
      if (!userId) {
        console.log('Skipping getProfile – no user ID from signUp');
        return;
      }

      const { data, error } = await authed.auth.getProfile(userId);

      expect(error).toBeNull();
      expect(data).toBeDefined();
    });

    it('should update the current user profile', async () => {
      const { client: authed, data: signUpData, error: err } = await signUpFreshUser();
      expect(err).toBeNull();
      if (!signUpData?.user?.id) {
        console.log('Skipping setProfile – no authenticated user');
        return;
      }

      const newName = 'Updated ' + Date.now();
      const { data, error } = await authed.auth.setProfile({ name: newName });

      if (error) {
        // May fail if token is not valid for profile updates (e.g. unverified)
        expect(error.statusCode).toBeDefined();
      } else {
        expect(data).toBeDefined();
      }
    });

    it('should persist profile changes', async () => {
      const { client: authed, data: signUpData, error: err } = await signUpFreshUser();
      expect(err).toBeNull();

      const userId = signUpData?.user?.id;
      if (!userId) {
        console.log('Skipping persist profile – no user ID from signUp');
        return;
      }

      const newName = 'Persist ' + Date.now();
      const { error: setErr } = await authed.auth.setProfile({ name: newName });
      if (setErr) {
        console.log('setProfile failed (unverified user?) – skipping');
        return;
      }

      const { data } = await authed.auth.getProfile(userId);
      expect(data).toBeDefined();
    });
  });

  // ================================================================
  // Email verification flow (send verification email)
  // ================================================================

  describe('resendVerificationEmail()', () => {
    it('should send a verification email or return structured error', async () => {
      const { email, error: signUpErr } = await signUpFreshUser();
      expect(signUpErr).toBeNull();

      const c = createClient();
      const { data, error } = await c.auth.resendVerificationEmail({ email });

      // Email service may be disabled – both success and structured error are acceptable
      if (error) {
        expect(error.statusCode).toBeDefined();
        expect(typeof error.message).toBe('string');
      } else {
        expect(data).toBeDefined();
        expect(data!.success).toBeDefined();
      }
    });
  });

  // ================================================================
  // Password reset flow
  // ================================================================

  describe('sendResetPasswordEmail()', () => {
    it('should send a reset password email or return structured error', async () => {
      const { email, error: signUpErr } = await signUpFreshUser();
      expect(signUpErr).toBeNull();

      const c = createClient();
      const { data, error } = await c.auth.sendResetPasswordEmail({ email });

      if (error) {
        expect(error.statusCode).toBeDefined();
        expect(typeof error.message).toBe('string');
      } else {
        expect(data).toBeDefined();
        expect(data!.success).toBeDefined();
      }
    });
  });

  describe('exchangeResetPasswordToken()', () => {
    it('should reject an invalid OTP', async () => {
      const { email, error: signUpErr } = await signUpFreshUser();
      expect(signUpErr).toBeNull();

      const c = createClient();
      const { error } = await c.auth.exchangeResetPasswordToken({
        email,
        otp: '000000',
      });

      expect(error).not.toBeNull();
    });
  });

  describe('resetPassword()', () => {
    it('should reject an invalid OTP', async () => {
      const c = createClient();
      const { error } = await c.auth.resetPassword({
        newPassword: 'NewP@ssword_123!',
        otp: 'invalid-token',
      });

      expect(error).not.toBeNull();
    });
  });

  // ================================================================
  // verifyEmail
  // ================================================================

  describe('verifyEmail()', () => {
    it('should reject an invalid verification code', async () => {
      const { email, error: signUpErr } = await signUpFreshUser();
      expect(signUpErr).toBeNull();

      const c = createClient();
      const { error } = await c.auth.verifyEmail({ email, otp: '000000' });

      expect(error).not.toBeNull();
    });
  });

  // ================================================================
  // signInWithIdToken (needs a real Google ID token – test error path)
  // ================================================================

  describe('signInWithIdToken()', () => {
    it('should reject an invalid token', async () => {
      const c = createClient();
      const { error } = await c.auth.signInWithIdToken({
        provider: 'google',
        token: 'invalid-id-token',
      });

      expect(error).not.toBeNull();
      expect(error!.statusCode).toBeGreaterThanOrEqual(400);
    });
  });

  // ================================================================
  // signInWithOAuth (server-mode path – skipBrowserRedirect)
  // ================================================================

  describe('signInWithOAuth()', () => {
    it('should return an OAuth URL for a built-in provider', async () => {
      const c = createClient();
      const { data, error } = await c.auth.signInWithOAuth('google', {
        redirectTo: 'http://localhost:3000/dashboard',
        skipBrowserRedirect: true,
      });

      // Provider may not be configured – both outcomes are valid
      if (error) {
        expect(error.statusCode).toBeDefined();
      } else {
        expect(data.url).toBeDefined();
        expect(typeof data.url).toBe('string');
      }
    });

    it('should return an OAuth URL for a custom provider', async () => {
      const c = createClient();
      const { data, error } = await c.auth.signInWithOAuth('custom-test-provider', {
        redirectTo: 'http://localhost:3000/dashboard',
        skipBrowserRedirect: true,
      });

      // Custom provider likely not configured – verify structured error
      if (error) {
        expect(error.statusCode).toBeDefined();
        expect(typeof error.message).toBe('string');
      } else {
        expect(data.url).toBeDefined();
      }
    });
  });

  // ================================================================
  // exchangeOAuthCode (test error path – invalid code)
  // ================================================================

  describe('exchangeOAuthCode()', () => {
    it('should reject an invalid authorization code', async () => {
      const c = createClient();
      const { error } = await c.auth.exchangeOAuthCode('invalid-code', 'invalid-verifier');

      expect(error).not.toBeNull();
    });
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import { HttpClient } from '../../../lib/http-client';
import { AuthChangeEvent, TokenManager } from '../../../lib/token-manager';
import * as tokenManagerModule from '../../../lib/token-manager';
import { Auth } from '../auth';

vi.mock('../helpers', async (importOriginal) => {
  const actual = await importOriginal<typeof import('../helpers')>();
  return {
    ...actual,
    generateCodeVerifier: vi.fn(() => 'a'.repeat(43)),
    generateCodeChallenge: vi.fn(() => Promise.resolve('b'.repeat(43))),
    storePkceVerifier: vi.fn(),
  };
});

function createJsonResponse(status: number, body: any): Response {
  const response = {
    ok: status >= 200 && status < 300,
    status,
    statusText: 'OK',
    headers: new Headers({ 'content-type': 'application/json' }),
    json: () => Promise.resolve(body),
    text: () => Promise.resolve(JSON.stringify(body)),
  } as Response;

  (response as any).clone = () => createJsonResponse(status, body);

  return response;
}

describe('Auth', () => {
  afterEach(() => {
    vi.restoreAllMocks();
  });
  describe('signInWithOAuth()', () => {
    it('sends provider-specific additionalParams during OAuth init', async () => {
      const fetchMock = vi.fn().mockResolvedValue(
        createJsonResponse(200, {
          authUrl: 'https://accounts.google.com/o/oauth2/v2/auth',
        })
      );
      const http = new HttpClient(
        {
          baseUrl: 'http://localhost:7130',
          fetch: fetchMock as any,
          retryCount: 0,
          timeout: 0,
        },
        new TokenManager()
      );
      const auth = new Auth(http, new TokenManager(), { isServerMode: true });

