  describe('signUp()', () => {
    it('does not persist a session when sign-up requires email verification', async () => {
      const fetchMock = vi.fn().mockResolvedValue(
        createJsonResponse(200, {
          user: { id: 'u1', email: 'user@example.com', emailVerified: false },
          accessToken: null,
          requireEmailVerification: true,
        })
      );
      const tokenManager = new TokenManager();
      const http = new HttpClient(
        { baseUrl: 'http://localhost:7130', fetch: fetchMock as any, retryCount: 0, timeout: 0 },
        tokenManager
      );
      const saveSessionSpy = vi.spyOn(tokenManager, 'saveSession');
      const setAuthTokenSpy = vi.spyOn(http, 'setAuthToken');
      const auth = new Auth(http, tokenManager, { isServerMode: false });

      const { data, error } = await auth.signUp({
        email: 'user@example.com',
        password: 'password123',
      });

      expect(error).toBeNull();
      expect(data?.requireEmailVerification).toBe(true);
      // No access token came back, so nothing may be persisted.
      expect(saveSessionSpy).not.toHaveBeenCalled();
      expect(setAuthTokenSpy).not.toHaveBeenCalled();
      expect(tokenManager.getAccessToken()).toBeNull();
    });

    it('does not persist a session when the response has an access token but no user', async () => {
      const fetchMock = vi.fn().mockResolvedValue(
        createJsonResponse(200, {
          accessToken: 'token-without-user',
        })
      );
      const tokenManager = new TokenManager();
      const http = new HttpClient(
        { baseUrl: 'http://localhost:7130', fetch: fetchMock as any, retryCount: 0, timeout: 0 },
        tokenManager
      );
      const saveSessionSpy = vi.spyOn(tokenManager, 'saveSession');
      const setAuthTokenSpy = vi.spyOn(http, 'setAuthToken');
      const auth = new Auth(http, tokenManager, { isServerMode: false });

      const { data, error } = await auth.signUp({
        email: 'user@example.com',
        password: 'password123',
      });

      expect(error).toBeNull();
      expect(data?.accessToken).toBe('token-without-user');
      // A session needs both a token and a user; without the user nothing may be persisted.
      expect(saveSessionSpy).not.toHaveBeenCalled();
      expect(setAuthTokenSpy).not.toHaveBeenCalled();
      expect(tokenManager.getAccessToken()).toBeNull();
    });

    it('persists the session in browser mode when the response has an access token and a user', async () => {
      const user = { id: 'u1', email: 'user@example.com', emailVerified: true };
      const fetchMock = vi.fn().mockResolvedValue(
        createJsonResponse(200, {
          user,
          accessToken: 'signed-up-token',
        })
      );
      const tokenManager = new TokenManager();
      const http = new HttpClient(
        { baseUrl: 'http://localhost:7130', fetch: fetchMock as any, retryCount: 0, timeout: 0 },
        tokenManager
      );
      const saveSessionSpy = vi.spyOn(tokenManager, 'saveSession');
      const setAuthTokenSpy = vi.spyOn(http, 'setAuthToken');
      const auth = new Auth(http, tokenManager, { isServerMode: false });

      const { data, error } = await auth.signUp({
        email: 'user@example.com',
        password: 'password123',
      });

      expect(error).toBeNull();
      expect(data?.accessToken).toBe('signed-up-token');
      // Token and user both present: the session must be persisted and the HTTP auth header set.
      expect(saveSessionSpy).toHaveBeenCalledTimes(1);
      expect(saveSessionSpy).toHaveBeenCalledWith(
        { accessToken: 'signed-up-token', user },
        AuthChangeEvent.SIGNED_IN
      );
      expect(setAuthTokenSpy).toHaveBeenCalledWith('signed-up-token');
      expect(tokenManager.getAccessToken()).toBe('signed-up-token');
      expect(tokenManager.getUser()).toEqual(user);
    });
  });

  describe('signInWithOtp()', () => {
    it('posts the email to the send-otp endpoint and returns the generic success payload', async () => {
      const fetchMock = vi.fn().mockResolvedValue(
        createJsonResponse(202, {
          success: true,
          message: 'If sign-in is available for this email, we have sent a verification code.',
        })
      );
      const http = new HttpClient(
        { baseUrl: 'http://localhost:7130', fetch: fetchMock as any, retryCount: 0, timeout: 0 },
        new TokenManager()
      );
      const auth = new Auth(http, new TokenManager(), { isServerMode: true });

      const { data, error } = await auth.signInWithOtp({ email: 'user@example.com' });

      expect(error).toBeNull();
      expect(data?.success).toBe(true);

      const [requestUrl, requestInit] = fetchMock.mock.calls[0] as [string, RequestInit];
      expect(new URL(requestUrl).pathname).toBe('/api/auth/email/send-otp');
      expect(JSON.parse(requestInit.body as string)).toEqual({ email: 'user@example.com' });
    });
  });

  describe('verifyOtp()', () => {
    it('verifies the code via the sessions endpoint with method "otp" and returns a session', async () => {
      const session = {
        user: { id: 'u1', email: 'user@example.com', emailVerified: true },
        accessToken: 'access-token',
        refreshToken: 'refresh-token',
      };
      const fetchMock = vi.fn().mockResolvedValue(createJsonResponse(200, session));
      const http = new HttpClient(
        { baseUrl: 'http://localhost:7130', fetch: fetchMock as any, retryCount: 0, timeout: 0 },
        new TokenManager()
      );
      const setAuthTokenSpy = vi.spyOn(http, 'setAuthToken');
      const setRefreshTokenSpy = vi.spyOn(http, 'setRefreshToken');
      const auth = new Auth(http, new TokenManager(), { isServerMode: true });

      const { data, error } = await auth.verifyOtp({
        email: 'user@example.com',
        otp: '123456',
        name: 'Ada Lovelace',
      });

      expect(error).toBeNull();
      expect(data?.accessToken).toBe('access-token');
      // The session must be persisted — this is what distinguishes verifyOtp from signInWithOtp.
      expect(setAuthTokenSpy).toHaveBeenCalledWith('access-token');
      expect(setRefreshTokenSpy).toHaveBeenCalledWith('refresh-token');

      const [requestUrl, requestInit] = fetchMock.mock.calls[0] as [string, RequestInit];
      const url = new URL(requestUrl);
      expect(url.pathname).toBe('/api/auth/sessions');
      expect(url.searchParams.get('client_type')).toBe('mobile');
      expect(JSON.parse(requestInit.body as string)).toEqual({
        method: 'otp',
        email: 'user@example.com',
        otp: '123456',
        name: 'Ada Lovelace',
      });
    });

    it('signs in through the browser sessions endpoint (no client_type) and stores the session', async () => {
      const session = {
        user: { id: 'u1', email: 'user@example.com', emailVerified: true },
        accessToken: 'access-token',
        refreshToken: 'refresh-token',
      };
      const fetchMock = vi.fn().mockResolvedValue(createJsonResponse(200, session));
      const tokenManager = new TokenManager();
      const http = new HttpClient(
        { baseUrl: 'http://localhost:7130', fetch: fetchMock as any, retryCount: 0, timeout: 0 },
        tokenManager
      );
      const auth = new Auth(http, tokenManager, { isServerMode: false });

      const { data, error } = await auth.verifyOtp({ email: 'user@example.com', otp: '123456' });

      expect(error).toBeNull();
      expect(data?.accessToken).toBe('access-token');
      // Browser mode persists the session to the token manager.
      expect(tokenManager.getAccessToken()).toBe('access-token');

      const url = new URL(fetchMock.mock.calls[0][0] as string);
      expect(url.pathname).toBe('/api/auth/sessions');
      expect(url.searchParams.get('client_type')).toBeNull();
    });
  });
});

import { describe, it, expect, beforeAll } from 'vitest';
import { signUpAndSignIn, getTestEnv } from './setup';
import type { InsForgeClient } from '../src/client';

/**
 * Storage integration tests.
 *
 * Exercises the full upload / list / download / delete lifecycle.
 *
 * Prerequisite: a bucket named `public` (or whatever BUCKET is set to)
 * must exist and allow authenticated uploads.
 *
 * Public methods tested:
 *   Storage.from(bucket) → StorageBucket
 *   StorageBucket.upload(path, file)
 *   StorageBucket.uploadAuto(file)
 *   StorageBucket.download(path)
 *   StorageBucket.getPublicUrl(path)
 *   StorageBucket.list(options)
 *   StorageBucket.remove(path)
 */

const BUCKET = 'public';
let bucketAvailable = true;

describe('Storage Module', () => {
  let client: InsForgeClient;
  let env: ReturnType<typeof getTestEnv>;

  beforeAll(async () => {
    env = getTestEnv();
    const result = await signUpAndSignIn();
    expect(result.error).toBeNull();
    client = result.client;

    // Probe the bucket – try a small upload to confirm it exists and accepts writes
    const probeKey = `_sdk_probe_${Date.now()}.txt`;
    const probe = new Blob(['probe'], { type: 'text/plain' });
    const { error } = await client.storage.from(BUCKET).upload(probeKey, probe);
    if (error) {
      bucketAvailable = false;
      console.warn(
        `⚠ Bucket "${BUCKET}" not available – storage tests will verify error handling only.`
      );
    } else {
      // Clean up probe file (best-effort)
      await client.storage
        .from(BUCKET)
        .remove(probeKey)
        .catch(() => {});
    }
  });

  // ================================================================
  // from() – factory method
  // ================================================================

  describe('from()', () => {
    it('should return a StorageBucket instance', () => {
      const bucket = client.storage.from(BUCKET);
      expect(bucket).toBeDefined();
      expect(typeof bucket.upload).toBe('function');
      expect(typeof bucket.uploadAuto).toBe('function');
      expect(typeof bucket.download).toBe('function');
      expect(typeof bucket.getPublicUrl).toBe('function');
      expect(typeof bucket.list).toBe('function');
      expect(typeof bucket.remove).toBe('function');
    });
  });

  // ================================================================
  // getPublicUrl  (pure client-side, always works)
  // ================================================================

  describe('getPublicUrl()', () => {
    it('should build a correct public URL', () => {
      const { data, error } = client.storage.from(BUCKET).getPublicUrl('images/logo.png');
      expect(error).toBeNull();
      expect(data?.publicUrl).toContain(env.baseUrl);
      expect(data?.publicUrl).toContain(BUCKET);
      expect(data?.publicUrl).toContain('images%2Flogo.png');
    });

    it('should handle nested paths', () => {
      const { data } = client.storage.from(BUCKET).getPublicUrl('a/b/c/file.txt');
      expect(data?.publicUrl).toContain('a%2Fb%2Fc%2Ffile.txt');
    });

    it('should handle paths with special characters', () => {
      const { data } = client.storage.from(BUCKET).getPublicUrl('files/my doc (1).pdf');
      expect(data?.publicUrl).toContain(BUCKET);
      // URL encoding should be applied
      expect(data?.publicUrl).toBeDefined();
    });
  });

  // ================================================================
  // list
  // ================================================================

  describe('list()', () => {
    it('should list objects in a bucket', async () => {
      const { data, error } = await client.storage.from(BUCKET).list({ limit: 10 });

      if (bucketAvailable && !error) {
        expect(data).toBeDefined();
      } else {
        // Bucket doesn't exist or list requires admin access
        expect(error !== null || (data !== null && typeof data === 'object')).toBe(true);
      }
    });

    it('should support prefix filtering', async () => {
      const { data, error } = await client.storage.from(BUCKET).list({ prefix: 'sdk-test/' });

      if (bucketAvailable && !error) {
        expect(data).toBeDefined();
      }
    });

    it('should support limit and offset', async () => {
      const { data, error } = await client.storage.from(BUCKET).list({ limit: 2, offset: 0 });

      if (bucketAvailable && !error) {
        expect(data).toBeDefined();
      }
    });

    it('should support search', async () => {
      const { data, error } = await client.storage.from(BUCKET).list({ search: 'integration' });

      if (bucketAvailable && !error) {
        expect(data).toBeDefined();
      }
    });
  });

  // ================================================================
  // Full file lifecycle: upload → list → download → remove
  // ================================================================

  describe('upload()', () => {
    const filePath = `sdk-test/upload-${Date.now()}.txt`;
    const fileContent = 'Upload test – ' + new Date().toISOString();

    it('should upload a file with a specific path', async () => {
      if (!bucketAvailable) {
        return;
      }

      const blob = new Blob([fileContent], { type: 'text/plain' });
      const { data, error } = await client.storage.from(BUCKET).upload(filePath, blob);

      expect(error).toBeNull();
      expect(data).not.toBeNull();
      expect(data!.key).toBeDefined();
    });

    it('should find the uploaded file in listings', async () => {
      if (!bucketAvailable) {
        return;
      }

      const { data } = await client.storage.from(BUCKET).list({ prefix: 'sdk-test/' });
      // File may or may not show immediately, but listing should work
      expect(data).toBeDefined();
    });

    it('should delete the uploaded file', async () => {
      if (!bucketAvailable) {
        return;
      }

      const { data, error } = await client.storage.from(BUCKET).remove(filePath);

      if (error) {
        // File might have already been deleted or not found
        expect(error.statusCode).toBeDefined();
      } else {
        expect(data).toBeDefined();
      }
    });
  });

  describe('uploadAuto()', () => {
    it('should upload a file with auto-generated key', async () => {
      if (!bucketAvailable) {
        return;
      }

      const content = 'Auto upload – ' + Date.now();
      const blob = new Blob([content], { type: 'text/plain' });

      // Create a File-like object (in Node the Blob is sufficient)
      const { data, error } = await client.storage.from(BUCKET).uploadAuto(blob);

      if (error) {
        // Some backends may not support auto key generation
        expect(error.statusCode).toBeDefined();
      } else {
        expect(data).not.toBeNull();
        expect(data!.key).toBeDefined();

        // Clean up
        await client.storage.from(BUCKET).remove(data!.key);
      }
    });
  });

  describe('download()', () => {
    it('should download a previously uploaded file', async () => {
      if (!bucketAvailable) {
        return;
      }

      const path = `sdk-test/download-${Date.now()}.txt`;
      const originalContent = 'Download test – ' + Date.now();
      const blob = new Blob([originalContent], { type: 'text/plain' });

      // Upload
      const { error: upErr } = await client.storage.from(BUCKET).upload(path, blob);
      expect(upErr).toBeNull();

      // Download
      const { data, error } = await client.storage.from(BUCKET).download(path);

      if (!error) {
        expect(data).toBeDefined();
        expect(data).toBeInstanceOf(Blob);
      }

      // Clean up
      await client.storage.from(BUCKET).remove(path);
    });

    it('should return error for non-existent file', async () => {
      const { error } = await client.storage.from(BUCKET).download(`nonexistent-${Date.now()}.txt`);

      expect(error).not.toBeNull();
    });
  });

  describe('remove()', () => {
    it('should return error or success for non-existent file', async () => {
      const { data, error } = await client.storage
        .from(BUCKET)
        .remove(`nonexistent-${Date.now()}.txt`);

      // Either succeeds with message or returns structured error
      expect(data !== null || error !== null).toBe(true);
    });
  });
});

import { describe, it, expect, beforeAll } from 'vitest';
import { signUpAndSignIn } from './setup';
import type { InsForgeClient } from '../src/client';

/**
 * Email module integration tests.
 *
 * Public API tested:
 *   emails.send(options)
 *
 * Email sending may be disabled or rate-limited on test projects.
 * Tests verify the SDK correctly forms the request and surfaces
 * either success or a structured error.
 */

describe('Email Module', () => {
  let authedClient: InsForgeClient;

  beforeAll(async () => {
    const result = await signUpAndSignIn();
    expect(result.error).toBeNull();
    authedClient = result.client;
  });

  describe('send()', () => {
    it('should send an email with required fields', async () => {
      const { data, error } = await authedClient.emails.send({
        to: 'sdk-test@test.insforge.dev',
        subject: 'SDK Integration Test – ' + new Date().toISOString(),
        html: '<p>Automated test from InsForge SDK integration tests.</p>',
      });

      if (error) {
        // Email not configured – verify structured error
        expect(error.statusCode).toBeDefined();
        expect(typeof error.message).toBe('string');
      } else {
        expect(data).toBeDefined();
      }
    });

    it('should send an email with all optional fields', async () => {
      const { data, error } = await authedClient.emails.send({
        to: ['sdk-test-a@test.insforge.dev', 'sdk-test-b@test.insforge.dev'],
        subject: 'SDK Full Fields Test',
        html: '<h1>Hello</h1><p>Body</p>',
      });

      if (error) {
        expect(error.statusCode).toBeDefined();
      } else {
        expect(data).toBeDefined();
      }
    });
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { signUpAndSignIn } from './setup';
import type { InsForgeClient } from '../src/client';

/**
 * Database integration tests.
 *
 * Exercises the postgrest-js query builder through the InsForge SDK.
 * Full request path: SDK → HttpClient → InsForge API → PostgREST.
 *
 * Prerequisite: a table `sdk_test` must exist on the test project.
 *   CREATE TABLE sdk_test (
 *     id         serial PRIMARY KEY,
 *     name       text NOT NULL,
 *     value      text,
 *     score      integer DEFAULT 0,
 *     created_at timestamptz DEFAULT now()
 *   );
 *
 * If the table doesn't exist the tests verify the SDK correctly
 * surfaces backend errors (and log a warning).
 */

const TABLE = 'sdk_test';

// Track whether the table is available so later describes can skip early
let tableAvailable = true;

describe('Database Module', () => {
  let client: InsForgeClient;
  const insertedIds: number[] = [];

  beforeAll(async () => {
    const result = await signUpAndSignIn();
    expect(result.error).toBeNull();
    client = result.client;

    // Probe the table
    const { error } = await client.database.from(TABLE).select('id').limit(1);
    if (error) {
      // Only downgrade for table-not-found errors; fail fast on auth/network/other issues
      const msg = (error.message || '').toLowerCase();
      const code = (error as any).code || '';
      if (
        code === '42P01' ||
        msg.includes('relation') ||
        msg.includes('not found') ||
        msg.includes('does not exist')
      ) {
        tableAvailable = false;
        console.warn(
          `⚠ Table "${TABLE}" not found – database tests will verify error handling only.`
        );
      } else {
        throw new Error(`Unexpected database error during probe: ${error.message} (code: ${code})`);
      }
    }
  });

  afterAll(async () => {
    if (insertedIds.length > 0 && tableAvailable) {
      await client.database.from(TABLE).delete().in('id', insertedIds);
    }
  });

  // ================================================================
  // SELECT
  // ================================================================

  describe('from().select()', () => {
    it('should return an array of rows', async () => {
      const { data, error } = await client.database.from(TABLE).select('*').limit(5);

      if (tableAvailable) {
        expect(error).toBeNull();
        expect(Array.isArray(data)).toBe(true);
      } else {
        expect(error).toBeDefined();
      }
    });

    it('should select specific columns', async () => {
      const { data, error } = await client.database.from(TABLE).select('id, name').limit(3);

      if (tableAvailable && !error) {
        expect(Array.isArray(data)).toBe(true);
        if (data!.length > 0) {
          // Only id and name should be returned
          expect(data![0]).toHaveProperty('id');
          expect(data![0]).toHaveProperty('name');
        }
      }
    });

    it('should support count-only queries (head: true)', async () => {
      const { count, error } = await client.database
        .from(TABLE)
        .select('*', { count: 'exact', head: true });

      if (tableAvailable) {
        expect(error).toBeNull();
        expect(typeof count).toBe('number');
      }
    });

    it('should return empty array for impossible filter', async () => {
      const { data, error } = await client.database
        .from(TABLE)
        .select('*')
        .eq('name', `nonexistent-${Date.now()}-${Math.random()}`);

      if (tableAvailable) {
        expect(error).toBeNull();
        expect(data).toEqual([]);
      }
    });
  });

  // ================================================================
  // INSERT
  // ================================================================

  describe('from().insert()', () => {
    it('should insert a single row and return it', async () => {
      if (!tableAvailable) {
        return;
      }

      const name = `insert-single-${Date.now()}`;
      const { data, error } = await client.database
        .from(TABLE)
        .insert({ name, value: 'single', score: 10 })
        .select()
        .single();

      expect(error).toBeNull();
      expect(data).toBeDefined();
      expect(data.name).toBe(name);
      expect(data.value).toBe('single');
      expect(data.score).toBe(10);
      expect(data.id).toBeDefined();
      insertedIds.push(data.id);
    });

    it('should insert multiple rows', async () => {
      if (!tableAvailable) {
        return;
      }

      const rows = [
        { name: `batch-a-${Date.now()}`, value: 'batch', score: 20 },
        { name: `batch-b-${Date.now()}`, value: 'batch', score: 30 },
      ];

      const { data, error } = await client.database.from(TABLE).insert(rows).select();

      expect(error).toBeNull();
      expect(Array.isArray(data)).toBe(true);
      expect(data!.length).toBe(2);
      data!.forEach((row: any) => insertedIds.push(row.id));
    });
  });

  // ================================================================
  // UPDATE
  // ================================================================

  describe('from().update()', () => {
    it('should update a row and return the result', async () => {
      if (!tableAvailable) {
        return;
      }

      // Insert first
      const tag = `update-${Date.now()}`;
      const { data: inserted } = await client.database
        .from(TABLE)
        .insert({ name: tag, value: 'before', score: 0 })
        .select()
        .single();
      if (!inserted) {
        return;
      }
      insertedIds.push(inserted.id);

      // Update
      const { data, error } = await client.database
        .from(TABLE)
        .update({ value: 'after', score: 99 })
        .eq('id', inserted.id)
        .select()
        .single();

      expect(error).toBeNull();
      expect(data.value).toBe('after');
      expect(data.score).toBe(99);
    });
  });

  // ================================================================
  // UPSERT
  // ================================================================

  describe('from().upsert()', () => {
    it('should insert when row does not exist', async () => {
      if (!tableAvailable) {
        return;
      }

      const tag = `upsert-${Date.now()}`;
      const { data, error } = await client.database
        .from(TABLE)
        .upsert({ name: tag, value: 'upserted', score: 50 })
        .select()
        .single();

      expect(error).toBeNull();
      expect(data).toBeDefined();
      expect(data.name).toBe(tag);
      insertedIds.push(data.id);
    });
  });

  // ================================================================
  // DELETE
  // ================================================================

  describe('from().delete()', () => {
    it('should delete matching rows', async () => {
      if (!tableAvailable) {
        return;
      }

      const tag = `delete-${Date.now()}`;
      const { data: inserted } = await client.database
        .from(TABLE)
        .insert({ name: tag, value: 'to-delete' })
        .select()
        .single();
      if (!inserted) {
        return;
      }

      const { error } = await client.database.from(TABLE).delete().eq('id', inserted.id);

      expect(error).toBeNull();

      // Verify it's gone
      const { data: check } = await client.database.from(TABLE).select('id').eq('id', inserted.id);

      expect(check).toEqual([]);
    });
  });

  // ================================================================
  // Filters & operators
  // ================================================================

  describe('filters', () => {
    let seedId: number;

    beforeAll(async () => {
      if (!tableAvailable) {
        return;
      }

      const rows = [
        { name: 'filter-alpha', value: 'hello world', score: 10 },
        { name: 'filter-beta', value: 'hello earth', score: 20 },
        { name: 'filter-gamma', value: 'goodbye world', score: 30 },
      ];

      const { data } = await client.database.from(TABLE).insert(rows).select();

      if (data) {
        data.forEach((r: any) => insertedIds.push(r.id));
        seedId = data[0].id;
      }
    });

    it('eq() should match exact value', async () => {
      if (!tableAvailable) {
        return;
      }
      const { data } = await client.database.from(TABLE).select('*').eq('name', 'filter-alpha');
      expect(data!.length).toBeGreaterThanOrEqual(1);
      expect(data![0].name).toBe('filter-alpha');
    });

    it('neq() should exclude exact value', async () => {
      if (!tableAvailable) {
        return;
      }
      const { data } = await client.database
        .from(TABLE)
        .select('name')
        .neq('name', 'filter-alpha')
        .like('name', 'filter-%');
      expect(data!.every((r: any) => r.name !== 'filter-alpha')).toBe(true);
    });

    it('gt() / lt() should compare numerically', async () => {
      if (!tableAvailable) {
        return;
      }
      const { data } = await client.database
        .from(TABLE)
        .select('name, score')
        .gt('score', 15)
        .lt('score', 25)
        .like('name', 'filter-%');
      expect(data!.length).toBeGreaterThanOrEqual(1);
      expect(data![0].score).toBe(20);
    });

    it('gte() / lte() should compare inclusive', async () => {
      if (!tableAvailable) {
        return;
      }
      const { data } = await client.database
        .from(TABLE)
        .select('name, score')
        .gte('score', 20)
        .lte('score', 30)
        .like('name', 'filter-%');
      expect(data!.length).toBeGreaterThanOrEqual(2);
    });

    it('like() should match pattern', async () => {
      if (!tableAvailable) {
        return;
      }
      const { data } = await client.database
        .from(TABLE)
        .select('value')
        .like('value', '%world%')
        .like('name', 'filter-%');
      expect(data!.length).toBeGreaterThanOrEqual(1);
      data!.forEach((r: any) => expect(r.value).toContain('world'));
    });

    it('ilike() should match case-insensitively', async () => {
      if (!tableAvailable) {
        return;
      }
      const { data } = await client.database
        .from(TABLE)
        .select('value')
        .ilike('value', '%HELLO%')
        .like('name', 'filter-%');
      expect(data!.length).toBeGreaterThanOrEqual(1);
    });

    it('in() should match multiple values', async () => {
      if (!tableAvailable) {
        return;
      }
      const { data } = await client.database
        .from(TABLE)
        .select('name')
        .in('name', ['filter-alpha', 'filter-gamma']);
      expect(data!.length).toBeGreaterThanOrEqual(2);
    });

    it('order() should sort results', async () => {
      if (!tableAvailable) {
        return;
      }
      const { data } = await client.database
        .from(TABLE)
        .select('score')
        .like('name', 'filter-%')
        .order('score', { ascending: true });
      if (data!.length >= 2) {
        expect(data![0].score).toBeLessThanOrEqual(data![1].score);
      }
    });

    it('limit() should cap result count', async () => {
      if (!tableAvailable) {
        return;
      }
      const { data } = await client.database
        .from(TABLE)
        .select('*')
        .like('name', 'filter-%')
        .limit(1);
      expect(data!.length).toBeLessThanOrEqual(1);
    });

    it('range() should paginate results', async () => {
      if (!tableAvailable) {
        return;
      }
      const { data } = await client.database
        .from(TABLE)
        .select('*')
        .like('name', 'filter-%')
        .range(0, 1);
      expect(data!.length).toBeLessThanOrEqual(2);
    });

    it('single() should return one row', async () => {
      if (!tableAvailable || !seedId) {
        return;
      }
      const { data, error } = await client.database
        .from(TABLE)
        .select('*')
        .eq('id', seedId)
        .single();
      expect(error).toBeNull();
      expect(data).toBeDefined();
      expect(data.id).toBe(seedId);
    });

    it('maybeSingle() should return null for no match', async () => {
      if (!tableAvailable) {
        return;
      }
      const { data, error } = await client.database
        .from(TABLE)
        .select('*')
        .eq('name', `no-match-${Date.now()}`)
        .maybeSingle();
      expect(error).toBeNull();
      expect(data).toBeNull();
    });
  });

  // ================================================================
  // RPC
  // ================================================================

  describe('rpc()', () => {
    it('should call an RPC function or return structured error', async () => {
      const { data, error } = await client.database.rpc('ping');

      // Function may not exist – both outcomes are valid
      if (error) {
        expect(error).toBeDefined();
      } else {
        expect(data).toBeDefined();
      }
    });
  });
});

import { describe, it, expect, expectTypeOf, vi, beforeEach } from 'vitest';
import { StorageBucket, type StorageResponse } from '../storage';
import { HttpClient } from '../../lib/http-client';
import { InsForgeError } from '../../types';
import { TokenManager } from '../../lib/token-manager';
import type { DeleteObjectsResponse } from '@insforge/shared-schemas';

function makeTokenManager(): TokenManager {
  return {
    saveSession: vi.fn(),
    clearSession: vi.fn(),
    getSession: vi.fn().mockReturnValue(null),
    getAccessToken: vi.fn().mockReturnValue(null),
  } as unknown as TokenManager;
}

function makeHttp(fetchFn: ReturnType<typeof vi.fn>) {
  return new HttpClient(
    {
      baseUrl: 'http://localhost:7130',
      fetch: fetchFn as any,
      retryCount: 0,
      timeout: 0,
    },
    makeTokenManager()
  );
}

function jsonRes(status: number, body: any, statusText = 'OK'): Response {
  return new Response(JSON.stringify(body), {
    status,
    statusText,
    headers: { 'content-type': 'application/json' },
  });
}

describe('StorageBucket.getPublicUrl', () => {
  beforeEach(() => {
    vi.restoreAllMocks();
  });

  it('returns { data: { publicUrl }, error } and makes no request', () => {
