      method: 'resumeSubscription',
      fallbackMessage: 'Razorpay subscription resume failed',
      call: (payments: Payments) => payments.razorpay.resumeSubscription('test', 'sub_123'),
    },
  ])(
    'surfaces $method unexpected errors as InsForgeError values',
    async ({ call, fallbackMessage }) => {
      const post = vi.fn().mockRejectedValue('unexpected failure');
      const payments = new Payments({ post } as unknown as HttpClient);

      const result = await call(payments);

      expect(result.data).toBeNull();
      expect(result.error).toBeInstanceOf(InsForgeError);
      expect(result.error?.error).toBe('UNEXPECTED_ERROR');
      expect(result.error?.statusCode).toBe(500);
      expect(result.error?.message).toBe(fallbackMessage);
    }
  );
});

name: Publish to npm

on:
  release:
    types: [published]
  push:
    tags:
      - 'v*'

concurrency:
  group: npm-publish-${{ github.event.release.tag_name || github.ref_name }}
  cancel-in-progress: false

jobs:
  publish:
    if: github.event_name == 'release' || contains(github.ref_name, '-')
    runs-on: ubuntu-latest
    permissions:
      contents: read
      id-token: write
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0

      - name: Validate release channel and version
        id: release
        env:
          EVENT_NAME: ${{ github.event_name }}
          RELEASE_TAG: ${{ github.event.release.tag_name || github.ref_name }}
          RELEASE_IS_PRERELEASE: ${{ github.event.release.prerelease || false }}
        run: |
          node <<'NODE'
          const { appendFileSync, readFileSync } = require('node:fs');

          const packageVersion = JSON.parse(readFileSync('package.json', 'utf8')).version;
          const tag = process.env.RELEASE_TAG;
          const eventName = process.env.EVENT_NAME;
          let distTag;

          if (eventName === 'release') {
            if (process.env.RELEASE_IS_PRERELEASE === 'true') {
              throw new Error('GitHub Releases may only publish stable versions');
            }
            if (!/^v\d+\.\d+\.\d+$/.test(tag)) {
              throw new Error(`Stable release tag must match vX.Y.Z; received ${tag}`);
            }
            distTag = 'latest';
          } else if (eventName === 'push') {
            const match = tag.match(/^v\d+\.\d+\.\d+-(alpha|beta|rc)\.\d+$/);
            if (!match) {
              throw new Error(
                `Prerelease tag must match vX.Y.Z-(alpha|beta|rc).N; received ${tag}`,
              );
            }
            distTag = match[1];
          } else {
            throw new Error(`Unsupported publish event: ${eventName}`);
          }

          const tagVersion = tag.slice(1);
          if (tagVersion !== packageVersion) {
            throw new Error(
              `Tag version ${tagVersion} does not match package.json version ${packageVersion}`,
            );
          }

          appendFileSync(process.env.GITHUB_OUTPUT, `dist_tag=${distTag}\n`);
          console.log(`Validated @insforge/sdk@${packageVersion} for npm tag ${distTag}`);
          NODE

      - name: Verify stable release commit is in main
        if: github.event_name == 'release'
        env:
          RELEASE_TAG: ${{ github.event.release.tag_name }}
        run: |
          release_commit="$(git rev-parse "${RELEASE_TAG}^{commit}")"
          if ! git merge-base --is-ancestor "$release_commit" origin/main; then
            echo "Stable release $RELEASE_TAG must point to a commit contained in main." >&2
            exit 1
          fi

      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: '24'
          registry-url: 'https://registry.npmjs.org'
          package-manager-cache: false

      - run: npm ci
      - run: npm run format:check
      - run: npm run lint
      - run: npm run typecheck
      - run: npm run test:run
      - run: npm run build
      - run: npm pack --dry-run

      - name: Publish package
        run: npm publish --access public --tag "${{ steps.release.outputs.dist_tag }}"

/**
 * Auth module helper functions
 */

import { InsForgeError } from '../../types';

// ============================================================================
// PKCE (Proof Key for Code Exchange) - RFC 7636
// ============================================================================

const PKCE_VERIFIER_KEY = 'insforge_pkce_verifier';

type WebCrypto = Pick<Crypto, 'getRandomValues' | 'subtle'>;

async function getWebCrypto(): Promise<WebCrypto> {
  const webCrypto = (
    globalThis as typeof globalThis & {
      crypto?: Partial<WebCrypto>;
    }
  ).crypto;

  if (typeof webCrypto?.getRandomValues === 'function' && webCrypto.subtle) {
    return webCrypto as WebCrypto;
  }

  if (typeof process !== 'undefined' && process.versions?.node) {
    const { webcrypto } = await import('node:crypto');
    return webcrypto as unknown as WebCrypto;
  }

  throw new Error('Web Crypto API is not available in this environment');
}

/**
 * Base64 URL encode without padding (per RFC 7636)
 */
function base64UrlEncode(buffer: Uint8Array): string {
  const base64 = btoa(String.fromCharCode(...buffer));
  return base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

/**
 * Generate a cryptographically random code verifier for PKCE
 */
export async function generateCodeVerifier(): Promise<string> {
  const webCrypto = await getWebCrypto();
  const array = new Uint8Array(32);
  webCrypto.getRandomValues(array);
  return base64UrlEncode(array);
}

/**
 * Generate code challenge from verifier using SHA-256 (S256 method)
 */
export async function generateCodeChallenge(verifier: string): Promise<string> {
  const webCrypto = await getWebCrypto();
  const encoder = new TextEncoder();
  const data = encoder.encode(verifier);
  const hash = await webCrypto.subtle.digest('SHA-256', data);
  return base64UrlEncode(new Uint8Array(hash));
}

/**
 * Store PKCE code verifier in sessionStorage
 */
export function storePkceVerifier(verifier: string): void {
  if (typeof sessionStorage !== 'undefined') {
    sessionStorage.setItem(PKCE_VERIFIER_KEY, verifier);
  }
}

/**
 * Retrieve and clear PKCE code verifier from sessionStorage
 */
export function retrievePkceVerifier(): string | null {
  if (typeof sessionStorage === 'undefined') {
    return null;
  }
  const verifier = sessionStorage.getItem(PKCE_VERIFIER_KEY);
  if (verifier) {
    sessionStorage.removeItem(PKCE_VERIFIER_KEY);
  }
  return verifier;
}

// ============================================================================
// Error Helpers
// ============================================================================

/**
 * Wrap an error into the standard { data, error } format
 * Passes through InsForgeError unchanged, wraps other errors
 */
export function wrapError<T>(
  error: unknown,
  fallbackMessage: string
): { data: T | null; error: InsForgeError } {
  if (error instanceof InsForgeError) {
    return { data: null, error };
  }

  return {
    data: null,
    error: new InsForgeError(
      error instanceof Error ? error.message : fallbackMessage,
      500,
      'UNEXPECTED_ERROR'
    ),
  };
}

/**
 * Clean up URL parameters (removes sensitive data from URL after OAuth callback)
 */
export function cleanUrlParams(...params: string[]): void {
  if (typeof window === 'undefined') {
    return;
  }

  const url = new URL(window.location.href);
  params.forEach((p) => url.searchParams.delete(p));
  window.history.replaceState({}, document.title, url.toString());
}

/**
 * Auth module for InsForge SDK
 * Handles authentication, sessions, profiles, and email verification
 */

import { HttpClient } from '../../lib/http-client';
import {
  TokenManager,
  AuthChangeEvent,
  getCsrfToken,
  setCsrfToken,
  clearCsrfToken,
  type AuthStateChangeCallback,
} from '../../lib/token-manager';
import { AuthSession, InsForgeError } from '../../types';
import {
  generateCodeVerifier,
  generateCodeChallenge,
  storePkceVerifier,
  retrievePkceVerifier,
  wrapError,
  cleanUrlParams,
} from './helpers';

import {
  ERROR_CODES,
  oAuthProvidersSchema,
  type CreateUserRequest,
  type CreateUserResponse,
  type CreateSessionRequest,
  type CreateSessionResponse,
  type SendOTPRequest,
  type GetOauthUrlResponse,
  type GetPublicAuthConfigResponse,
  type OAuthInitRequest,
  type OAuthProvidersSchema,
  type SendVerificationEmailRequest,
  type SendResetPasswordEmailRequest,
  type ExchangeResetPasswordTokenRequest,
  type ExchangeResetPasswordTokenResponse,
  type VerifyEmailRequest,
  type VerifyEmailResponse,
  type RefreshSessionResponse,
  type ResetPasswordResponse,
  type UserSchema,
  type GetProfileResponse,
  type OAuthCodeExchangeRequest,
} from '@insforge/shared-schemas';

interface AuthOptions {
  isServerMode?: boolean;
  detectOAuthCallback?: boolean;
}

type OAuthSignInOptions = {
  redirectTo: string;
  additionalParams?: Record<string, string>;
  skipBrowserRedirect?: boolean;
};

type OAuthSignInLegacyOptions = OAuthSignInOptions & {
  provider: OAuthProvidersSchema | string;
};

/** Credentials for the password sign-in flow (excludes the OTP session variant). */
export type PasswordSessionRequest = Exclude<CreateSessionRequest, { method: 'otp' }>;

/** Payload for {@link Auth.verifyOtp}: the email OTP session variant without the discriminator. */
export type VerifyOtpRequest = Omit<Extract<CreateSessionRequest, { method: 'otp' }>, 'method'>;

export class Auth {
  private authCallbackHandled: Promise<void>;

  constructor(
    private http: HttpClient,
    private tokenManager: TokenManager,
    private options: AuthOptions = {}
  ) {
    this.authCallbackHandled =
      options.detectOAuthCallback === false ? Promise.resolve() : this.detectAuthCallback();
  }

  private isServerMode(): boolean {
    return !!this.options.isServerMode;
  }

  /** Subscribe to SDK authentication state changes. */
  onAuthStateChange(callback: AuthStateChangeCallback): () => void {
    return this.tokenManager.onAuthStateChange(callback);
  }

  /**
   * Save session from API response
   * Handles token storage, CSRF token, and HTTP auth header
   */
  private saveSessionFromResponse(
    response:
      CreateUserResponse | CreateSessionResponse | VerifyEmailResponse | RefreshSessionResponse,
    event: AuthChangeEvent = AuthChangeEvent.SIGNED_IN
  ): boolean {
    if (!response.accessToken || !response.user) {
      return false;
    }

    const session: AuthSession = {
      accessToken: response.accessToken,
      user: response.user,
    };

    // Browser web flow: csrf token is returned for cookie-based refresh
    if (!this.isServerMode() && response.csrfToken) {
      setCsrfToken(response.csrfToken);
    }

    if (!this.isServerMode()) {
      this.tokenManager.saveSession(session, event);
    }
    this.http.setAuthToken(response.accessToken);
    this.http.setRefreshToken(response.refreshToken ?? null);
    return true;
  }

  // ============================================================================
  // OAuth Callback Detection (runs on initialization)
  // ============================================================================

  /**
   * Detect and handle OAuth callback parameters in URL
   * Supports PKCE flow (insforge_code)
   */
  private async detectAuthCallback(): Promise<void> {
    if (this.isServerMode() || typeof window === 'undefined') {
      return;
    }

    try {
      const params = new URLSearchParams(window.location.search);

      // Handle error callback
      const error = params.get('error');
      if (error) {
        cleanUrlParams('error');
        console.debug('OAuth callback error:', error);
        return;
      }

      // PKCE flow: exchange code for tokens
      const code = params.get('insforge_code');
      if (code) {
        cleanUrlParams('insforge_code');
        const { error: exchangeError } = await this.exchangeOAuthCode(code);
        if (exchangeError) {
          console.debug('OAuth code exchange failed:', exchangeError.message);
        }
        return;
      }
    } catch (error) {
      console.debug('OAuth callback detection skipped:', error);
    }
  }

  // ============================================================================
  // Sign Up / Sign In / Sign Out
  // ============================================================================

  async signUp(request: CreateUserRequest): Promise<{
    data: CreateUserResponse | null;
    error: InsForgeError | null;
  }> {
    try {
      const response = await this.http.post<CreateUserResponse>(
        this.isServerMode() ? '/api/auth/users?client_type=mobile' : '/api/auth/users',
        request,
        { credentials: 'include', skipAuthRefresh: true }
      );

      this.saveSessionFromResponse(response);
      if (response.refreshToken) {
        this.http.setRefreshToken(response.refreshToken);
      }

      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred during sign up');
    }
  }

  async signInWithPassword(request: PasswordSessionRequest): Promise<{
    data: CreateSessionResponse | null;
    error: InsForgeError | null;
  }> {
    try {
      const response = await this.http.post<CreateSessionResponse>(
        this.isServerMode() ? '/api/auth/sessions?client_type=mobile' : '/api/auth/sessions',
        request,
        { credentials: 'include', skipAuthRefresh: true }
      );

      this.saveSessionFromResponse(response);
      if (response.refreshToken) {
        this.http.setRefreshToken(response.refreshToken);
      }

      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred during sign in');
    }
  }

  /**
   * Send a one-time sign-in code to an email address.
   *
   * The response is intentionally generic whether or not an account exists, to
   * avoid account enumeration. Complete the flow with {@link Auth.verifyOtp}.
   */
  async signInWithOtp(request: SendOTPRequest): Promise<{
    data: { success: boolean; message: string } | null;
    error: InsForgeError | null;
  }> {
    try {
      const response = await this.http.post<{ success: boolean; message: string }>(
        '/api/auth/email/send-otp',
        request,
        { skipAuthRefresh: true }
      );
      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred while sending the sign-in code');
    }
  }

  /**
   * Verify an email sign-in code and create a session.
   *
   * If the email is new, a verified passwordless user is created; `name` sets
   * the display name only on that first-time creation.
   */
  async verifyOtp(request: VerifyOtpRequest): Promise<{
    data: CreateSessionResponse | null;
    error: InsForgeError | null;
  }> {
    try {
      const response = await this.http.post<CreateSessionResponse>(
        this.isServerMode() ? '/api/auth/sessions?client_type=mobile' : '/api/auth/sessions',
        // method is set last so it can never be clobbered by an untyped caller's payload.
        { ...request, method: 'otp' },
        { credentials: 'include', skipAuthRefresh: true }
      );

      this.saveSessionFromResponse(response);
      if (response.refreshToken) {
        this.http.setRefreshToken(response.refreshToken);
      }

      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred during sign in');
    }
  }

  async signOut(): Promise<{ error: InsForgeError | null }> {
    try {
      // Try backend logout first
      try {
        const serverMode = this.isServerMode();
        const csrfToken = !serverMode ? getCsrfToken() : null;
        await this.http.post(
          serverMode ? '/api/auth/logout?client_type=mobile' : '/api/auth/logout',
          undefined,
          {
            credentials: 'include',
            skipAuthRefresh: true,
            ...(csrfToken ? { headers: { 'X-CSRF-Token': csrfToken } } : {}),
          }
        );
      } catch {
        // Ignore backend logout failure so local state is still cleared
      }

      this.tokenManager.clearSession();
      this.http.setAuthToken(null);
      this.http.setRefreshToken(null);
      if (!this.isServerMode()) {
        clearCsrfToken();
      }

      return { error: null };
    } catch {
      return {
        error: new InsForgeError('Failed to sign out', 500, 'SIGNOUT_ERROR'),
      };
    }
  }

  // ============================================================================
  // OAuth Authentication
  // ============================================================================

  /**
   * Sign in with OAuth provider using PKCE flow
   */
  async signInWithOAuth(
    provider: OAuthProvidersSchema | string,
    options: OAuthSignInOptions
  ): Promise<{
    data: { url?: string; provider?: string; codeVerifier?: string };
    error: InsForgeError | null;
  }>;
  /**
   * @deprecated Use signInWithOAuth(provider, { redirectTo, additionalParams, skipBrowserRedirect }).
   */
  async signInWithOAuth(options: OAuthSignInLegacyOptions): Promise<{
    data: { url?: string; provider?: string; codeVerifier?: string };
    error: InsForgeError | null;
  }>;
  async signInWithOAuth(
    providerOrOptions: OAuthProvidersSchema | string | OAuthSignInLegacyOptions,
    options?: OAuthSignInOptions
  ): Promise<{
    data: { url?: string; provider?: string; codeVerifier?: string };
    error: InsForgeError | null;
  }> {
    try {
      let signInOptions: OAuthSignInLegacyOptions;

      if (typeof providerOrOptions === 'object') {
        signInOptions = providerOrOptions;
      } else if (options) {
        signInOptions = { provider: providerOrOptions, ...options };
      } else {
        return {
          data: {},
          error: new InsForgeError(
            'OAuth sign-in options are required',
            400,
            ERROR_CODES.INVALID_INPUT
          ),
        };
      }

      if (!signInOptions || !signInOptions.redirectTo) {
        return {
          data: {},
          error: new InsForgeError('Redirect URI is required', 400, ERROR_CODES.INVALID_INPUT),
        };
      }

      const { provider } = signInOptions;
      const providerKey = encodeURIComponent(provider.toLowerCase());

      const codeVerifier = await generateCodeVerifier();
      const codeChallenge = await generateCodeChallenge(codeVerifier);
      storePkceVerifier(codeVerifier);

      const params: OAuthInitRequest = {
        ...(signInOptions.additionalParams ?? {}),
        redirect_uri: signInOptions.redirectTo,
        code_challenge: codeChallenge,
      };

      const isBuiltInProvider = oAuthProvidersSchema.options.includes(
        providerKey as OAuthProvidersSchema
      );
      const oauthPath = isBuiltInProvider
        ? `/api/auth/oauth/${providerKey}`
        : `/api/auth/oauth/custom/${providerKey}`;

      const response = await this.http.get<GetOauthUrlResponse>(oauthPath, {
        params,
        skipAuthRefresh: true,
      });

      if (
        !this.isServerMode() &&
        typeof window !== 'undefined' &&
        !signInOptions.skipBrowserRedirect
      ) {
        window.location.href = response.authUrl;
        return { data: {}, error: null };
      }

      return {
        data: { url: response.authUrl, provider: providerKey, codeVerifier },
        error: null,
      };
    } catch (error) {
      if (error instanceof InsForgeError) {
        return { data: {}, error };
      }
      return {
        data: {},
        error: new InsForgeError(
          'An unexpected error occurred during OAuth initialization',
          500,
          'UNEXPECTED_ERROR'
        ),
      };
    }
  }

  /**
   * Exchange OAuth authorization code for tokens (PKCE flow)
   * Called automatically on initialization when insforge_code is in URL
   */
  async exchangeOAuthCode(
    code: string,
    codeVerifier?: string
  ): Promise<{
    data: CreateSessionResponse | null;
    error: InsForgeError | null;
  }> {
    try {
      const verifier = codeVerifier ?? retrievePkceVerifier();

      if (!verifier) {
        return {
          data: null,
          error: new InsForgeError(
            'PKCE code verifier not found. Ensure signInWithOAuth was called in the same browser session.',
            400,
            'PKCE_VERIFIER_MISSING'
          ),
        };
      }

      const request: OAuthCodeExchangeRequest = {
        code,
        code_verifier: verifier,
      };
      const response = await this.http.post<CreateSessionResponse>(
        this.isServerMode()
          ? '/api/auth/oauth/exchange?client_type=mobile'
          : '/api/auth/oauth/exchange',
        request,
        { credentials: 'include', skipAuthRefresh: true }
      );

      this.saveSessionFromResponse(response);

      return {
        data: response,
        error: null,
      };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred during OAuth code exchange');
    }
  }

  /**
   * Sign in with an ID token from a native SDK (Google One Tap, etc.)
   * Use this for native mobile apps or Google One Tap on web.
   *
   * @param credentials.provider - The identity provider (currently only 'google' is supported)
   * @param credentials.token - The ID token from the native SDK
   */
  async signInWithIdToken(credentials: { provider: 'google'; token: string }): Promise<{
    data: CreateSessionResponse | null;
    error: InsForgeError | null;
  }> {
    try {
      const { provider, token } = credentials;

      const response = await this.http.post<CreateSessionResponse>(
        '/api/auth/id-token?client_type=mobile',
        { provider, token },
        { credentials: 'include', skipAuthRefresh: true }
      );

      this.saveSessionFromResponse(response);
      if (response.refreshToken) {
        this.http.setRefreshToken(response.refreshToken);
      }

      return {
        data: response,
        error: null,
      };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred during ID token sign in');
    }
  }

  // ============================================================================
  // Session Management
  // ============================================================================

  /**
   * Refresh the current auth session.
   *
   * Browser mode:
   * - Uses httpOnly refresh cookie and optional CSRF header.
   *
   * Legacy server mode (`isServerMode: true`):
   * - Uses mobile auth flow and requires `refreshToken` in request body.
   *
   * SSR apps should prefer `createRefreshAuthRouter()` / `refreshAuth()` from
   * `@insforge/sdk/ssr`.
   */
  async refreshSession(options?: { refreshToken?: string }): Promise<{
    data: RefreshSessionResponse | null;
    error: InsForgeError | null;
  }> {
    try {
      if (this.isServerMode() && !options?.refreshToken) {
        return {
          data: null,
          error: new InsForgeError(
            'refreshToken is required when refreshing session in server mode',
            400,
            ERROR_CODES.AUTH_UNAUTHORIZED
          ),
        };
      }

      const csrfToken = !this.isServerMode() ? getCsrfToken() : null;

      const response = await this.http.post<RefreshSessionResponse>(
        this.isServerMode() ? '/api/auth/refresh?client_type=mobile' : '/api/auth/refresh',
        this.isServerMode() ? { refresh_token: options?.refreshToken } : undefined,
        {
          headers: csrfToken ? { 'X-CSRF-Token': csrfToken } : {},
          credentials: 'include',
          skipAuthRefresh: true,
        }
      );

      if (response.accessToken) {
        this.saveSessionFromResponse(response, AuthChangeEvent.TOKEN_REFRESHED);
      }

      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred during session refresh');
    }
  }

  /**
   * Get current user, automatically waits for pending OAuth callback
   */
  async getCurrentUser(): Promise<{
    data: { user: UserSchema | null };
    error: InsForgeError | null;
  }> {
    await this.authCallbackHandled;

    try {
      if (this.isServerMode()) {
        const accessToken = this.tokenManager.getAccessToken();
        if (!accessToken) {
          return { data: { user: null }, error: null };
        }

        this.http.setAuthToken(accessToken);
        const response = await this.http.get<{ user: UserSchema }>('/api/auth/sessions/current');
        const user = response.user ?? null;
        return { data: { user }, error: null };
      }

      // Browser mode: check memory first
      const session = this.tokenManager.getSession();
      if (session) {
        this.http.setAuthToken(session.accessToken);
        return { data: { user: session.user }, error: null };
      }

      // Try refresh via httpOnly cookie (browser only)
      if (typeof window !== 'undefined') {
        const { data: refreshed, error: refreshError } = await this.refreshSession();
        if (refreshError) {
          return { data: { user: null }, error: refreshError };
        }
        if (refreshed?.accessToken) {
          return { data: { user: refreshed.user ?? null }, error: null };
        }
      }

      return { data: { user: null }, error: null };
    } catch (error) {
      if (error instanceof InsForgeError) {
        return { data: { user: null }, error };
      }
      return {
        data: { user: null },
        error: new InsForgeError(
          'An unexpected error occurred while getting user',
          500,
          'UNEXPECTED_ERROR'
        ),
      };
    }
  }

  // ============================================================================
  // Profile Management
  // ============================================================================

  async getProfile(userId: string): Promise<{
    data: GetProfileResponse | null;
    error: InsForgeError | null;
  }> {
    try {
      const response = await this.http.get<GetProfileResponse>(`/api/auth/profiles/${userId}`);
      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred while fetching user profile');
    }
  }

  async setProfile(profile: Record<string, unknown>): Promise<{
    data: GetProfileResponse | null;
    error: InsForgeError | null;
  }> {
    try {
      const response = await this.http.patch<GetProfileResponse>('/api/auth/profiles/current', {
        profile,
      });

      const currentUser = this.tokenManager.getUser();
      if (!this.isServerMode() && currentUser && response.profile !== undefined) {
        this.tokenManager.setUser({
          ...currentUser,
          profile: response.profile,
        });
      }

      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred while updating user profile');
    }
  }

  // ============================================================================
  // Email Verification
  // ============================================================================

  async resendVerificationEmail(request: SendVerificationEmailRequest): Promise<{
    data: { success: boolean; message: string } | null;
    error: InsForgeError | null;
  }> {
    try {
      const response = await this.http.post<{
        success: boolean;
        message: string;
      }>('/api/auth/email/send-verification', request, {
        skipAuthRefresh: true,
      });
      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred while sending verification email');
    }
  }

  async verifyEmail(request: VerifyEmailRequest): Promise<{
    data: VerifyEmailResponse | null;
    error: InsForgeError | null;
  }> {
    try {
      const response = await this.http.post<VerifyEmailResponse>(
        this.isServerMode()
          ? '/api/auth/email/verify?client_type=mobile'
          : '/api/auth/email/verify',
        request,
        { credentials: 'include', skipAuthRefresh: true }
      );

      this.saveSessionFromResponse(response);
      if (response.refreshToken) {
        this.http.setRefreshToken(response.refreshToken);
      }
      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred while verifying email');
    }
  }

  // ============================================================================
  // Password Reset
  // ============================================================================

  async sendResetPasswordEmail(request: SendResetPasswordEmailRequest): Promise<{
    data: { success: boolean; message: string } | null;
    error: InsForgeError | null;
  }> {
    try {
      const response = await this.http.post<{
        success: boolean;
        message: string;
      }>('/api/auth/email/send-reset-password', request, {
        skipAuthRefresh: true,
      });
      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred while sending password reset email');
    }
  }

  async exchangeResetPasswordToken(request: ExchangeResetPasswordTokenRequest): Promise<{
    data: ExchangeResetPasswordTokenResponse | null;
    error: InsForgeError | null;
  }> {
    try {
      const response = await this.http.post<ExchangeResetPasswordTokenResponse>(
        '/api/auth/email/exchange-reset-password-token',
        request,
        { skipAuthRefresh: true }
      );
      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred while verifying reset code');
    }
  }

  async resetPassword(request: { newPassword: string; otp: string }): Promise<{
    data: ResetPasswordResponse | null;
    error: InsForgeError | null;
  }> {
    try {
      const response = await this.http.post<ResetPasswordResponse>(
        '/api/auth/email/reset-password',
        request,
        { skipAuthRefresh: true }
      );
      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred while resetting password');
    }
  }

  // ============================================================================
  // Configuration
  // ============================================================================

  async getPublicAuthConfig(): Promise<{
    data: GetPublicAuthConfigResponse | null;
    error: InsForgeError | null;
  }> {
    try {
      const response = await this.http.get<GetPublicAuthConfigResponse>('/api/auth/public-config', {
        skipAuthRefresh: true,
      });
      return { data: response, error: null };
    } catch (error) {
      return wrapError(error, 'An unexpected error occurred while fetching auth configuration');
    }
  }
}

import { InsForgeClient } from '../client';
import { AuthChangeEvent } from '../lib/token-manager';
import { InsForgeError, type AuthRefreshResponse, type InsForgeConfig } from '../types';
import { isJwtExpiredOrExpiring } from '../lib/jwt';
import { ERROR_CODES } from '@insforge/shared-schemas';
import { getAccessTokenCookieName, getBrowserCookie, type AuthCookieSettings } from './cookies';

type BrowserAuth = Pick<
  InsForgeClient['auth'],
  'getCurrentUser' | 'getProfile' | 'getPublicAuthConfig'
>;

export type BrowserInsForgeClient = Omit<InsForgeClient, 'auth'> & {
  readonly auth: BrowserAuth;
};

export interface CreateBrowserClientOptions
  extends
    Omit<InsForgeConfig, 'accessToken' | 'edgeFunctionToken' | 'isServerMode' | 'auth'>,
    AuthCookieSettings {
  refreshUrl?: string;
  refreshLeewaySeconds?: number;
}

async function parseRefreshResponse(response: Response): Promise<unknown> {
  const contentType = response.headers.get('content-type');
  if (contentType?.includes('json')) {
    return await response.json();
  }
  return await response.text();
}

function toRefreshError(response: Response, body: unknown): InsForgeError {
  if (body && typeof body === 'object') {
    const errorBody = body as {
      error?: unknown;
      message?: unknown;
      statusCode?: unknown;
    };
    return new InsForgeError(
      typeof errorBody.message === 'string' ? errorBody.message : 'Failed to refresh auth session',
      typeof errorBody.statusCode === 'number' ? errorBody.statusCode : response.status,
      typeof errorBody.error === 'string' ? errorBody.error : ERROR_CODES.UNKNOWN_ERROR
    );
  }

  return new InsForgeError(
    typeof body === 'string' && body ? body : 'Failed to refresh auth session',
    response.status,
    ERROR_CODES.UNKNOWN_ERROR
  );
}

async function readErrorCode(response: Response): Promise<string | null> {
  if (response.status !== 401) {
    return null;
  }

  try {
    const body = await response.clone().json();
    if (!body || typeof body !== 'object') {
      return null;
    }
    const candidate =
      (body as { error?: unknown; code?: unknown }).error ?? (body as { code?: unknown }).code;
    return typeof candidate === 'string' ? candidate : null;
  } catch {
    return null;
  }
}

function isRefreshableErrorCode(code: string | null): boolean {
  return (
    code === ERROR_CODES.AUTH_UNAUTHORIZED ||
    code === ERROR_CODES.AUTH_TOKEN_EXPIRED ||
    code === 'PGRST301'
  );
}

function withAuthHeader(init: RequestInit | undefined, token: string): RequestInit {
  const headers = new Headers(init?.headers);
  headers.set('Authorization', `Bearer ${token}`);
  return {
    ...init,
    headers,
  };
}

function getRequestUrl(input: RequestInfo | URL): string {
  if (typeof input === 'string') {
    return input;
  }
  if (typeof Request !== 'undefined' && input instanceof Request) {
    return input.url;
  }
  return input.toString();
}

export function createBrowserClient(
  options: CreateBrowserClientOptions = {}
): BrowserInsForgeClient {
  let { baseUrl, anonKey } = options;
  try {
    baseUrl ||= process.env.NEXT_PUBLIC_INSFORGE_URL;
    anonKey ||= process.env.NEXT_PUBLIC_INSFORGE_ANON_KEY;
  } catch {
    // process may be unavailable outside Next.js/browser-bundled envs.
  }
  if (!baseUrl || !anonKey) {
    throw new Error(
      'Missing InsForge baseUrl or anonKey. Pass baseUrl and anonKey to createBrowserClient() or set NEXT_PUBLIC_INSFORGE_URL and NEXT_PUBLIC_INSFORGE_ANON_KEY.'
    );
  }

  let accessToken = getBrowserCookie(getAccessTokenCookieName(options.names));
  const refreshUrl = options.refreshUrl ?? '/api/auth/refresh';
  const fetchImpl =
    options.fetch ??
    (globalThis.fetch
      ? globalThis.fetch.bind(globalThis)
      : (undefined as typeof fetch | undefined));
  let client: InsForgeClient;
  let sessionChecked = false;
  let refreshPromise: Promise<AuthRefreshResponse | null> | null = null;

  const refreshFromRoute = (): Promise<AuthRefreshResponse | null> => {
    if (refreshPromise) {
      return refreshPromise;
    }

    refreshPromise = (async () => {
      if (!fetchImpl) {
        throw new Error('Fetch is not available. Please provide a fetch implementation.');
      }

      const response = await fetchImpl(refreshUrl, {
        method: 'POST',
        credentials: 'include',
        headers: { Accept: 'application/json' },
      });
      const body = await parseRefreshResponse(response);

      if (!response.ok) {
        const error = toRefreshError(response, body);
        if (
          response.status === 401 &&
          (error.error === ERROR_CODES.AUTH_UNAUTHORIZED ||
            error.error === ERROR_CODES.AUTH_TOKEN_EXPIRED)
        ) {
          accessToken = null;
          client?.setAccessToken(null);
          return null;
        }
        throw error;
      }

      if (!body || typeof body !== 'object') {
        return null;
      }
      const refreshBody = body as Partial<AuthRefreshResponse>;
      if (!refreshBody.accessToken || !refreshBody.user) {
        return null;
      }

      accessToken = refreshBody.accessToken;
      client?.setAccessToken(refreshBody.accessToken, AuthChangeEvent.TOKEN_REFRESHED);
      return refreshBody as AuthRefreshResponse;
    })().finally(() => {
      sessionChecked = true;
      refreshPromise = null;
    });

    return refreshPromise;
  };

  const shouldSkipRefresh = (input: RequestInfo | URL): boolean => {
    const url = getRequestUrl(input);
    return url === refreshUrl || url.endsWith(refreshUrl);
  };

  const ssrFetch: typeof fetch = async (input, init) => {
    if (!fetchImpl) {
      throw new Error('Fetch is not available. Please provide a fetch implementation.');
    }
    if (shouldSkipRefresh(input)) {
      return fetchImpl(input, init);
    }

    let requestInit = init;
    if (
      (!accessToken && !sessionChecked) ||
      isJwtExpiredOrExpiring(accessToken, options.refreshLeewaySeconds)
    ) {
      const refreshed = await refreshFromRoute().catch(() => null);
      if (refreshed?.accessToken) {
        requestInit = withAuthHeader(init, refreshed.accessToken);
      }
    }

    const response = await fetchImpl(input, requestInit);
    const errorCode = await readErrorCode(response);
    if (!isRefreshableErrorCode(errorCode)) {
      return response;
    }

    const refreshed = await refreshFromRoute();
    if (!refreshed?.accessToken) {
      client.setAccessToken(null);
      return response;
    }

    return fetchImpl(input, withAuthHeader(init, refreshed.accessToken));
  };

  client = new InsForgeClient({
    ...options,
    baseUrl,
    anonKey,
    fetch: ssrFetch,
    // Browser clients manage tokens via the refresh route, not a static
    // config token; shadow any untyped accessToken in the options spread.
    accessToken: undefined,
    auth: {
      detectOAuthCallback: false,
    },
  });
  const setAccessToken = client.setAccessToken.bind(client);
  client.setAccessToken = (token: string | null, event) => {
    accessToken = token;
    setAccessToken(token, event);
  };

  if (accessToken) {
    client.setAccessToken(accessToken);
  }

  if (!accessToken || isJwtExpiredOrExpiring(accessToken, options.refreshLeewaySeconds)) {
    void refreshFromRoute().catch(() => undefined);
  }

  // Runtime still returns the normal client object; SSR auth mutation guardrails
  // are enforced by the public TypeScript surface.
  return client as unknown as BrowserInsForgeClient;
}

# insforge-sdk-js

[![npm version](https://img.shields.io/npm/v/@insforge/sdk.svg)](https://www.npmjs.com/package/@insforge/sdk)
[![License](https://img.shields.io/badge/License-Apache%202.0-blue.svg)](https://opensource.org/licenses/Apache-2.0)

Official TypeScript/JavaScript SDK for [InsForge](https://github.com/InsForge/InsForge) - A powerful, open-source Backend-as-a-Service (BaaS) platform.

## Features

- **Authentication** - Email/password, OAuth (Google, GitHub), session management
- **Database** - Full PostgreSQL database access with PostgREST
- **Storage** - File upload and management with S3-compatible storage
- **Edge Functions** - Serverless function invocation
- **AI Integration** - Built-in AI capabilities
- **Payments** - Stripe Checkout and Billing Portal session helpers
- **TypeScript** - Full TypeScript support with type definitions
- **Automatic OAuth Handling** - Seamless OAuth callback detection

## Installation

```bash
npm install @insforge/sdk
```

Or with yarn:

```bash
yarn add @insforge/sdk
```

## Quick Start

### Initialize the Client

```javascript
import { createClient } from '@insforge/sdk';

const insforge = createClient({
  baseUrl: 'http://localhost:7130', // Your InsForge backend URL
  anonKey: 'your-anon-key', // Optional public anon key
});
```

### Server Admin Client

Use `createAdminClient()` only in trusted server code that needs project-admin privileges:

```typescript
import { createAdminClient } from '@insforge/sdk';

const admin = createAdminClient({
  baseUrl: 'http://localhost:7130',
  apiKey: process.env.INSFORGE_API_KEY!,
});
```

`apiKey` belongs in `createAdminClient()`. Public and user-scoped clients use `anonKey`.

### Acting as a User on the Server

In edge functions or other server code that receives a user's JWT, seed the client with it via `accessToken`:

```javascript
const insforge = createClient({
  baseUrl: 'http://localhost:7130',
  accessToken: userJwt, // e.g. from the request's Authorization header
});
```

All requests run as that user (RLS applies). The token is used as-is — the SDK does not refresh it. `edgeFunctionToken` is a deprecated alias for this option.

### Authentication

```javascript
// Sign up a new user
const { data, error } = await insforge.auth.signUp({
  email: 'user@example.com',
  password: 'securePassword123',
  name: 'John Doe', // optional
  redirectTo: 'http://localhost:3000/sign-in', // optional, recommended for link-based verification
});

// Sign in with email/password
const { data, error } = await insforge.auth.signInWithPassword({
  email: 'user@example.com',
  password: 'securePassword123',
});

// OAuth authentication (built-in or custom provider key)
await insforge.auth.signInWithOAuth('google', {
  redirectTo: 'http://localhost:3000/dashboard',
  additionalParams: { prompt: 'select_account' },
});
// additionalParams is for provider-specific hints only.
// Do not pass client_id, scope, redirect_uri, code_challenge, state, or response_type;
// InsForge sets server-owned OAuth fields and ignores colliding client-provided keys.

// Get current user (call this during browser app startup)
const { data: currentUser } = await insforge.auth.getCurrentUser();

// Get any user's profile by ID (public endpoint)
const { data: profile, error } = await insforge.auth.getProfile('user-id-here');

// Update current user's profile (requires authentication)
const { data: updatedProfile, error } = await insforge.auth.setProfile({
  displayName: 'John Doe',
  bio: 'Software developer',
  avatarUrl: 'https://example.com/avatar.jpg',
});

// Sign out
await insforge.auth.signOut();
```

### Email Verification And Password Reset

```javascript
// Resend a verification email
await insforge.auth.resendVerificationEmail({
  email: 'user@example.com',
  redirectTo: 'http://localhost:3000/sign-in', // optional, recommended for link-based verification
});

// Verify email with a 6-digit code
await insforge.auth.verifyEmail({
  email: 'user@example.com',
  otp: '123456',
});

// Send password reset email
await insforge.auth.sendResetPasswordEmail({
  email: 'user@example.com',
  redirectTo: 'http://localhost:3000/reset-password', // optional, recommended for link-based reset
});

// Code-based reset flow: exchange the code, then reset the password
const { data: resetToken } = await insforge.auth.exchangeResetPasswordToken({
  email: 'user@example.com',
  code: '123456',
});

if (resetToken) {
  await insforge.auth.resetPassword({
    newPassword: 'newSecurePassword123',
    otp: resetToken.token,
  });
}
```

For link-based verification and password reset, users click the emailed browser links:

- `GET /api/auth/email/verify-link`
- `GET /api/auth/email/reset-password-link`

Those backend endpoints validate the token first, then redirect the browser to your `redirectTo` URL.

- Verification links redirect with `insforge_status=success|error`, `insforge_type=verify_email`, and optional `insforge_error`
- Recommended: use your sign-in page as the verification `redirectTo`, then show a confirmation message and ask the user to sign in with email and password
- Reset links redirect with `token` when ready, plus `insforge_status=ready|error`, `insforge_type=reset_password`, and optional `insforge_error`

### Database Operations

```javascript
// Insert data
const { data, error } = await insforge.database
  .from('posts')
  .insert([{ title: 'My First Post', content: 'Hello World!' }]);

// Query data
const { data, error } = await insforge.database.from('posts').select('*').eq('author_id', userId);

// Update data
const { data, error } = await insforge.database
  .from('posts')
  .update({ title: 'Updated Title' })
  .eq('id', postId);

// Delete data
const { data, error } = await insforge.database.from('posts').delete().eq('id', postId);
```

#### Selecting a schema

Queries hit the `public` schema by default. Target a custom schema by chaining `.schema()` — the table name stays bare (it maps to PostgREST's `Accept-Profile`/`Content-Profile` header):

```javascript
const { data } = await insforge.database.schema('analytics').from('events').select('*');

await insforge.database.schema('analytics').rpc('rollup', { day: '2026-01-01' });
```

Or set a default schema for every query when creating the client:

```javascript
const insforge = createClient({
  baseUrl: '...',
  anonKey: '...',
  db: { schema: 'analytics' },
});
```

The schema must be exposed by the backend, and access is still gated by grants + RLS like `public`. Older backends that don't expose the schema return PostgREST `PGRST106` rather than silently falling back.

### File Storage

```javascript
// Upload a file
const file = document.querySelector('input[type="file"]').files[0];
const { data, error } = await insforge.storage.from('avatars').upload(file);

// Download a file
const { data, error } = await insforge.storage.from('avatars').download('user-avatar.png');

// Delete a file
const { data, error } = await insforge.storage.from('avatars').remove('user-avatar.png');

// Delete multiple files (maximum 1000 keys)
const { data, error } = await insforge.storage
  .from('avatars')
  .remove(['user-avatar.png', 'old-avatar.png']);
// data: { results: [{ key, status: 'deleted' | 'notFound' | 'failed', message? }] }

// List files
const { data, error } = await insforge.storage.from('avatars').list();
```

### Edge Functions

```javascript
// Invoke an edge function
const { data, error } = await insforge.functions.invoke('my-function', {
  body: { key: 'value' },
});
```

### Payments

```javascript
// Create and redirect to a Stripe Checkout Session
const { data, error } = await insforge.payments.stripe.createCheckoutSession('test', {
  mode: 'payment',
  lineItems: [{ priceId: 'price_123', quantity: 1 }],
  successUrl: `${window.location.origin}/success`,
  cancelUrl: `${window.location.origin}/pricing`,
  idempotencyKey: 'cart_123',
});

if (!error && data?.checkoutSession.url) {
  window.location.assign(data.checkoutSession.url);
}

// Create a subscription checkout for an app billing subject
const { data: subscriptionCheckout } = await insforge.payments.stripe.createCheckoutSession(
  'test',
  {
    mode: 'subscription',
    subject: { type: 'team', id: 'team_123' },
    lineItems: [{ priceId: 'price_monthly_123', quantity: 1 }],
    successUrl: `${window.location.origin}/billing/success`,
    cancelUrl: `${window.location.origin}/billing`,
  }
);

if (subscriptionCheckout?.checkoutSession.url) {
  window.location.assign(subscriptionCheckout.checkoutSession.url);
}

// Let an authenticated customer manage their subscription in Stripe Billing Portal
const { data: portal } = await insforge.payments.stripe.createCustomerPortalSession('test', {
  subject: { type: 'team', id: 'team_123' },
  returnUrl: `${window.location.origin}/billing`,
});

if (portal?.customerPortalSession.url) {
  window.location.assign(portal.customerPortalSession.url);
}

// Create a Razorpay order, then pass checkoutOptions to Razorpay Checkout.js
const { data: order } = await insforge.payments.razorpay.createOrder('test', {
  amount: 200000,
  currency: 'INR',
  subject: { type: 'team', id: 'team_123' },
  customerEmail: 'ada@example.com',
  notes: { order_id: 'order_123' },
});

if (order) {
  const checkout = new Razorpay({
    ...order.checkoutOptions,
    handler: async (response) => {
      await insforge.payments.razorpay.verifyOrder('test', {
        orderId: response.razorpay_order_id,
        paymentId: response.razorpay_payment_id,
        signature: response.razorpay_signature,
      });
    },
  });
  checkout.open();
}

// Create a Razorpay subscription checkout for an app billing subject
const { data: subscription } = await insforge.payments.razorpay.createSubscription('test', {
  planId: 'plan_123',
  totalCount: 12,
  subject: { type: 'team', id: 'team_123' },
  notes: { order_id: 'order_123' },
});
```

### AI Integration

AI methods return an OpenAI-like response object directly (not the `{ data, error }` envelope used by the other modules) and throw on failure.

```javascript
// Chat completion
const completion = await insforge.ai.chat.completions.create({
  model: 'anthropic/claude-3.5-haiku',
  messages: [{ role: 'user', content: 'Write a hello world program' }],
});
console.log(completion.choices[0].message.content);

// Streaming chat — returns an async iterable of chunks
const stream = await insforge.ai.chat.completions.create({
  model: 'anthropic/claude-3.5-haiku',
  messages: [{ role: 'user', content: 'Tell me a story' }],
  stream: true,
});
for await (const chunk of stream) {
  process.stdout.write(chunk.choices[0]?.delta?.content ?? '');
}

// Generate an image — returns base64-encoded image data
const image = await insforge.ai.images.generate({
  model: 'google/gemini-3-pro-image-preview',
  prompt: 'A sunset over mountains',
});
const base64Png = image.data[0].b64_json;

// Create embeddings
const embeddings = await insforge.ai.embeddings.create({
  model: 'openai/text-embedding-3-small',
  input: 'Hello world',
});
console.log(embeddings.data[0].embedding); // number[]
```

## Documentation

For complete API reference and advanced usage, see:

- **[SDK Reference](./SDK-REFERENCE.md)** - Complete API documentation
- **[InsForge Main Repository](https://github.com/InsForge/InsForge)** - Backend platform and setup guides

## Configuration

The SDK supports the following configuration options:

```javascript
const insforge = createClient({
  baseUrl: 'http://localhost:7130', // Your InsForge backend URL
  anonKey: 'your-anon-key', // Optional
});
```

For project-admin keys, use `createAdminClient({ apiKey })` in server-only code.

### SSR / Next.js

Use `@insforge/sdk/ssr` for apps that need the same auth session in Server Components, Client Components, Storage, and Realtime.
The helper uses explicit `baseUrl` / `anonKey` when provided. Otherwise it reads `NEXT_PUBLIC_INSFORGE_URL` / `NEXT_PUBLIC_INSFORGE_ANON_KEY`. Missing config throws a clear error.

By default, the SSR helpers use:

- `insforge_access_token`: browser-readable access token cookie, expires at the JWT `exp`
- `insforge_refresh_token`: httpOnly refresh token cookie, expires at the JWT `exp`

```typescript
// app/lib/insforge/client.ts
import { createBrowserClient } from '@insforge/sdk/ssr';

export const insforge = createBrowserClient();
```

`createBrowserClient()` is for Client Components that consume an existing SSR
session. Its TypeScript surface does not include auth mutations such as
`signInWithPassword()`, `signUp()`, or `signOut()`. Run auth mutations on the
server so the app can write server-owned auth cookies.

```typescript
// app/lib/insforge/server.ts
import { cookies } from 'next/headers';
import { createServerClient } from '@insforge/sdk/ssr';

export async function createInsForgeServerClient() {
  return createServerClient({ cookies: await cookies() });
}
```

```typescript
// app/api/auth/refresh/route.ts
import { createRefreshAuthRouter } from '@insforge/sdk/ssr';

export const { POST } = createRefreshAuthRouter();
```

For sign-in, sign-up, and sign-out, use `createAuthActions()` in a Server
Action file. Server Actions are stable in Next.js 14+. Do not return raw auth
responses from Server Actions; return only the user or app-specific safe fields
so access and refresh tokens stay server-owned.

```typescript
// app/actions.ts
'use server';

import { cookies } from 'next/headers';
import { createAuthActions } from '@insforge/sdk/ssr';

export async function signIn(formData: FormData) {
  const auth = createAuthActions({ cookies: await cookies() });

  const { data, error } = await auth.signInWithPassword({
    email: String(formData.get('email')),
    password: String(formData.get('password')),
  });

  return { user: data?.user ?? null, error };
}
```

For OAuth in SSR apps, start and finish the flow on the server. Store the PKCE
verifier in an httpOnly app cookie and exchange the callback code with
`createAuthActions()`:

```typescript
// app/actions.ts
'use server';

import { cookies } from 'next/headers';
import { redirect } from 'next/navigation';
import { createAuthActions } from '@insforge/sdk/ssr';

export async function signInWithGoogle() {
  const cookieStore = await cookies();
  const auth = createAuthActions({ cookies: cookieStore });
  const { data, error } = await auth.signInWithOAuth('google', {
    redirectTo: new URL('/api/auth/callback', process.env.NEXT_PUBLIC_APP_URL).toString(),
    skipBrowserRedirect: true,
  });

  if (error || !data.url || !data.codeVerifier) {
    throw new Error(error?.message ?? 'OAuth init failed');
  }

  cookieStore.set('insforge_code_verifier', data.codeVerifier, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 600,
  });

  redirect(data.url);
}
```

```typescript
// app/api/auth/callback/route.ts
import { cookies } from 'next/headers';
import { NextResponse, type NextRequest } from 'next/server';
import { createAuthActions } from '@insforge/sdk/ssr';

export async function GET(request: NextRequest) {
  const code = request.nextUrl.searchParams.get('insforge_code');
  const verifier = (await cookies()).get('insforge_code_verifier')?.value;
  if (!code || !verifier) {
    return NextResponse.redirect(new URL('/login?error=oauth', request.url));
  }

  const response = NextResponse.redirect(new URL('/dashboard', request.url));
  const auth = createAuthActions({
    requestCookies: request.cookies,
    responseCookies: response.cookies,
  });
  const { error } = await auth.exchangeOAuthCode(code, verifier);
  if (error) {
    return NextResponse.redirect(new URL('/login?error=oauth', request.url));
  }

  response.cookies.delete('insforge_code_verifier');
  return response;
}
```

SSR browser clients do not exchange OAuth callbacks automatically. OAuth
callbacks must be completed on the server so the refresh token lands in the
httpOnly app cookie.

For Route Handlers, pass request cookies for reading the current session and
response cookies for writing the next session:

```typescript
// app/api/auth/sign-out/route.ts
import { NextResponse, type NextRequest } from 'next/server';
import { createAuthActions } from '@insforge/sdk/ssr';

export async function POST(request: NextRequest) {
  const response = NextResponse.json({ ok: true });
  const auth = createAuthActions({
    requestCookies: request.cookies,
    responseCookies: response.cookies,
  });

  const { error } = await auth.signOut();
  if (error) {
    return NextResponse.json(
      { error: error.error, message: error.message },
      { status: error.statusCode }
    );
  }

  return response;
}
```

If your refresh route needs custom side effects:

```typescript
import { refreshAuth } from '@insforge/sdk/ssr';

export async function POST(request: Request) {
  const result = await refreshAuth({ request });
  // run app-specific side effects here
  return result.response;
}
```

For Next.js Proxy/Middleware, refresh before Server Components render:

```typescript
// proxy.ts on Next.js 16+, middleware.ts on Next.js 15 and earlier
import { NextResponse, type NextRequest } from 'next/server';
import { updateSession } from '@insforge/sdk/ssr/middleware';

export async function proxy(request: NextRequest) {
  const response = NextResponse.next({ request });

  await updateSession({
    requestCookies: request.cookies,
    responseCookies: response.cookies,
  });

  return response;
}
```

Use the `/ssr/middleware` subpath in Proxy/Middleware files. It only includes
the session refresh helpers and avoids bundling the full SDK client.

## TypeScript Support

The SDK is written in TypeScript and provides full type definitions:

```typescript
import { createClient, InsForgeClient } from '@insforge/sdk';

const insforge: InsForgeClient = createClient({
  baseUrl: 'http://localhost:7130',
});

// Type-safe API calls
const response = await insforge.auth.getCurrentUser();
```

## Error Handling

All SDK methods return a consistent response format:

```javascript
const { data, error } = await insforge.auth.signUp({...});

if (error) {
  console.error('Error:', error.message);
  console.error('Status:', error.statusCode);
} else {
  console.log('Success:', data);
}
```

## Browser Support

The SDK works in all modern browsers that support:

- ES6+ features
- Fetch API
- Cookies (for refresh token flow)

For Node.js environments, ensure you're using Node.js 18 or higher.

