import { describe, it, expect, beforeAll } from 'vitest';
import { createClient, getTestEnv } from './setup';
import { InsForgeClient } from '../src/client';

/**
 * Edge Functions integration tests.
 *
 * Public API tested:
 *   functions.invoke(slug)                         – default POST
 *   functions.invoke(slug, { method: 'GET' })      – GET
 *   functions.invoke(slug, { body })               – with body
 *   functions.invoke(slug, { headers })            – with custom headers
 *   functions.invoke(slug, { method: 'PUT' })      – PUT
 *   functions.invoke(slug, { method: 'PATCH' })    – PATCH
 *   functions.invoke(slug, { method: 'DELETE' })   – DELETE
 *
 * NOTE: Deploy a `hello-world` function on the test project for full
 * coverage. If absent, tests verify the SDK correctly surfaces 404/errors.
 */

describe('Functions Module', () => {
  let client: InsForgeClient;

  beforeAll(() => {
    client = createClient();
  });

  // ================================================================
  // invoke – POST (default)
  // ================================================================

  describe('invoke() – POST', () => {
    it('should invoke a function with POST and return data or structured error', async () => {
      const { data, error } = await client.functions.invoke('hello-world', {
        body: { name: 'SDK Integration Test' },
      });

      if (error) {
        expect(error.statusCode).toBeDefined();
        expect(typeof error.message).toBe('string');
      } else {
        expect(data).toBeDefined();
      }
    });
  });

  // ================================================================
  // invoke – GET
  // ================================================================

  describe('invoke() – GET', () => {
    it('should invoke a function with GET', async () => {
      const { data, error } = await client.functions.invoke('hello-world', {
        method: 'GET',
      });

      if (error) {
        expect(error.statusCode).toBeDefined();
      } else {
        expect(data).toBeDefined();
      }
    });
  });

  // ================================================================
  // invoke – other HTTP methods
  // ================================================================

  describe('invoke() – PUT', () => {
    it('should invoke with PUT method', async () => {
      const { data, error } = await client.functions.invoke('hello-world', {
        method: 'PUT',
        body: { action: 'put-test' },
      });

      expect(data !== null || error !== null).toBe(true);
    });
  });

  describe('invoke() – PATCH', () => {
    it('should invoke with PATCH method', async () => {
      const { data, error } = await client.functions.invoke('hello-world', {
        method: 'PATCH',
        body: { action: 'patch-test' },
      });

      expect(data !== null || error !== null).toBe(true);
    });
  });

  describe('invoke() – DELETE', () => {
    it('should invoke with DELETE method', async () => {
      const { data, error } = await client.functions.invoke('hello-world', {
        method: 'DELETE',
      });

      expect(data !== null || error !== null).toBe(true);
    });
  });

  // ================================================================
  // invoke – custom headers
  // ================================================================

  describe('invoke() – custom headers', () => {
    it('should forward custom headers to the function', async () => {
      const { data, error } = await client.functions.invoke('hello-world', {
        body: { echo: true },
        headers: {
          'X-Custom-Test': 'integration',
          'X-Request-Id': `test-${Date.now()}`,
        },
      });

      // Just verify it doesn't crash
      expect(data !== null || error !== null).toBe(true);
    });
  });

  // ================================================================
  // invoke – 404 (non-existent function)
  // ================================================================

  describe('invoke() – non-existent function', () => {
    it('should return a structured error for missing function', async () => {
      const slug = `nonexistent-fn-${Date.now()}`;
      const { data, error } = await client.functions.invoke(slug);

      expect(error).not.toBeNull();
      expect(error!.statusCode).toBeDefined();
      expect(typeof error!.message).toBe('string');
      expect(data).toBeNull();
    });
  });

  // ================================================================
  // invoke – no options (bare call)
  // ================================================================

  describe('invoke() – bare call', () => {
    it('should invoke with defaults (POST, no body, no headers)', async () => {
      const { data, error } = await client.functions.invoke('hello-world');

      if (error) {
        expect(error.statusCode).toBeDefined();
      } else {
        expect(data).toBeDefined();
      }
    });
  });

  // ================================================================
  // invoke – custom functionsUrl (subhosting → proxy fallback)
  // ================================================================

  describe('invoke() – custom functionsUrl', () => {
    it('should fall back to proxy when functionsUrl returns 404', async () => {
      const env = getTestEnv();
      // Point functionsUrl to a URL that will 404, forcing fallback to proxy
      const customClient = new InsForgeClient({
        baseUrl: env.baseUrl,
        anonKey: env.anonKey,
        functionsUrl: `${env.baseUrl}/nonexistent-subhosting`,
        isServerMode: true,
      });

      const { data, error } = await customClient.functions.invoke('hello-world');

      // Should either succeed via proxy fallback, or return a structured error
      if (error) {
        expect(error.statusCode).toBeDefined();
        expect(typeof error.message).toBe('string');
      } else {
        expect(data).toBeDefined();
      }
    });
  });
});

import { describe, it, expect, beforeAll, afterAll, afterEach } from 'vitest';
import type { SubscribeResponse } from '@insforge/shared-schemas';
import { createClient } from './setup';
import type { InsForgeClient } from '../src/client';

/**
 * Realtime module integration tests.
 *
 * Public API tested:
 *   realtime.connect()
 *   realtime.disconnect()
 *   realtime.subscribe(channel)
 *   realtime.unsubscribe(channel)
 *   realtime.publish(channel, event, payload)
 *   realtime.on(event, callback)
 *   realtime.off(event, callback)
 *   realtime.once(event, callback)
 *   realtime.getSubscribedChannels()
 *   realtime.isConnected          (getter)
 *   realtime.connectionState      (getter)
 *   realtime.socketId             (getter)
 *
 * NOTE: Realtime requires a socket.io server on the test project.
 * These API-level tests intentionally use the project's anonymous access
 * policy. Authenticated handshake token selection is covered by unit tests,
 * so these tests do not depend on the fixed test user's channel RLS policy.
 * If the server is unreachable the tests verify that errors are
 * properly surfaced rather than crashing.
 */

function expectSuccessfulSubscription(response: SubscribeResponse, channel: string): void {
  const failure = response.ok
    ? undefined
    : `${response.error?.code ?? 'UNKNOWN'}: ${response.error?.message ?? 'No error message'}`;

  expect(response, failure).toMatchObject({ ok: true, channel });
}

describe('Realtime Module', () => {
  let client: InsForgeClient;
  let realtimeAvailable = true;

  beforeAll(() => {
    client = createClient();
  });

  afterAll(() => {
    // Always disconnect to avoid hanging sockets
    try {
      client.realtime.disconnect();
    } catch {
      /* ignore */
    }
  });

  // ================================================================
  // Pre-connection state
  // ================================================================

  describe('initial state', () => {
    it('isConnected should be false before connect()', () => {
      const c = createClient();
      expect(c.realtime.isConnected).toBe(false);
    });

    it('connectionState should be "disconnected"', () => {
      const c = createClient();
      expect(c.realtime.connectionState).toBe('disconnected');
    });

    it('socketId should be undefined', () => {
      const c = createClient();
      expect(c.realtime.socketId).toBeUndefined();
    });

    it('getSubscribedChannels() should be empty', () => {
      const c = createClient();
      expect(c.realtime.getSubscribedChannels()).toEqual([]);
    });
  });

  // ================================================================
  // connect / disconnect
  // ================================================================

  describe('connect()', () => {
    it('should connect or throw a meaningful error', async () => {
      try {
        await client.realtime.connect();
        realtimeAvailable = true;
      } catch (err: any) {
        realtimeAvailable = false;
        // Connection may fail (server down, not configured)
        expect(err.message).toBeDefined();
        console.warn('⚠ Realtime not available:', err.message);
        return;
      }

      // Assertions outside try/catch so failures are not masked
      expect(client.realtime.isConnected).toBe(true);
      expect(client.realtime.connectionState).toBe('connected');
      expect(client.realtime.socketId).toBeDefined();
    });
  });

  describe('disconnect()', () => {
    it('should disconnect cleanly', async () => {
      if (!realtimeAvailable) {
        return;
      }

      // Ensure connected first
      if (!client.realtime.isConnected) {
        try {
          await client.realtime.connect();
        } catch {
          return;
        }
      }

      client.realtime.disconnect();
      expect(client.realtime.isConnected).toBe(false);
      expect(client.realtime.connectionState).toBe('disconnected');
    });

    it('should be safe to call when already disconnected', () => {
      const c = createClient();
      // Should not throw
      c.realtime.disconnect();
      expect(c.realtime.isConnected).toBe(false);
    });
  });

  // ================================================================
  // subscribe / unsubscribe
  // ================================================================

  describe('subscribe() / unsubscribe()', () => {
    beforeAll(async () => {
      if (!realtimeAvailable) {
        return;
      }
      try {
        await client.realtime.connect();
      } catch {
        realtimeAvailable = false;
      }
    });

    afterEach(() => {
      // Clean up subscriptions
      for (const ch of client.realtime.getSubscribedChannels()) {
        client.realtime.unsubscribe(ch);
      }
    });

    it('should subscribe to a channel', async () => {
      if (!realtimeAvailable) {
        return;
      }

      const channel = `test-${Date.now()}`;
      const response = await client.realtime.subscribe(channel);

      expect(response).toBeDefined();
      expectSuccessfulSubscription(response, channel);
      expect(client.realtime.getSubscribedChannels()).toContain(channel);
    });

    it('should return success for duplicate subscribe', async () => {
      if (!realtimeAvailable) {
        return;
      }

      const channel = `dup-${Date.now()}`;
      const first = await client.realtime.subscribe(channel);
      expectSuccessfulSubscription(first, channel);
      const second = await client.realtime.subscribe(channel);

      // Second call returns cached success
      expectSuccessfulSubscription(second, channel);
    });

    it('unsubscribe() should remove the channel', async () => {
      if (!realtimeAvailable) {
        return;
      }

      const channel = `unsub-${Date.now()}`;
      const response = await client.realtime.subscribe(channel);
      expectSuccessfulSubscription(response, channel);
      expect(client.realtime.getSubscribedChannels()).toContain(channel);

      client.realtime.unsubscribe(channel);
      expect(client.realtime.getSubscribedChannels()).not.toContain(channel);
    });
  });

  // ================================================================
  // on / off / once
  // ================================================================

  describe('on() / off() / once()', () => {
    it('on() should register an event listener', () => {
      const c = createClient();
      const cb = () => {};
      // Should not throw
      c.realtime.on('test-event', cb);
    });

    it('off() should remove an event listener', () => {
      const c = createClient();
      const cb = () => {};
      c.realtime.on('test-event', cb);
      c.realtime.off('test-event', cb);
      // No public way to check listener count, but should not throw
    });

    it('once() should register a one-shot listener', () => {
      const c = createClient();
      const cb = () => {};
      // Should not throw
      c.realtime.once('test-event', cb);
    });
  });

  // ================================================================
  // publish
  // ================================================================

  describe('publish()', () => {
    it('should throw when not connected', async () => {
      const c = createClient();
      await expect(
        c.realtime.publish('test-channel', 'test-event', { msg: 'hello' })
      ).rejects.toThrow(/not connected/i);
    });

    it('should publish when connected', async () => {
      if (!realtimeAvailable) {
        return;
      }

      if (!client.realtime.isConnected) {
        try {
          await client.realtime.connect();
        } catch {
          return;
        }
      }

      const channel = `pub-${Date.now()}`;
      const response = await client.realtime.subscribe(channel);
      expectSuccessfulSubscription(response, channel);

      // Should not throw
      await client.realtime.publish(channel, 'test-event', { ts: Date.now() });
    });
  });

  // ================================================================
  // getSubscribedChannels
  // ================================================================

  describe('getSubscribedChannels()', () => {
    it('should return an array of channel names', async () => {
      if (!realtimeAvailable) {
        return;
      }

      if (!client.realtime.isConnected) {
        try {
          await client.realtime.connect();
        } catch {
          return;
        }
      }

      const ch1 = `ch1-${Date.now()}`;
      const ch2 = `ch2-${Date.now()}`;
      const response1 = await client.realtime.subscribe(ch1);
      const response2 = await client.realtime.subscribe(ch2);
      expectSuccessfulSubscription(response1, ch1);
      expectSuccessfulSubscription(response2, ch2);

      const channels = client.realtime.getSubscribedChannels();
      expect(Array.isArray(channels)).toBe(true);
      expect(channels).toContain(ch1);
      expect(channels).toContain(ch2);

      // Cleanup
      client.realtime.unsubscribe(ch1);
      client.realtime.unsubscribe(ch2);
    });
  });
});
